import React from 'react';
import { Target, FileText, Code, ChevronRight, Briefcase, TrendingUp } from 'lucide-react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { useCareer } from '../../contexts/CareerContext';
import { useResumeInsights } from '../../hooks/useResumeInsights';

export default function AIInsightsSummary() {
  const { careerContext } = useCareer();
  const { atsScore, missingSkills: resumeMissingSkills, nextAction: resumeNextAction } = useResumeInsights();
  const navigate = useNavigate();

  // Consolidate missing skills from both contexts
  const skillsToImprove = [...new Set([...(careerContext?.missingSkills || []), ...(resumeMissingSkills || [])])].slice(0, 4);

  // Data-driven Status Logic
  const getStatusInfo = () => {
    const hasStrongResume = atsScore > 75;
    const hasWeakGithub = careerContext?.githubScore < 50;

    if (hasStrongResume && hasWeakGithub) {
      return {
        status: "Strong resume, but missing practical project evidence.",
        action: "Build and deploy 2 target projects to GitHub."
      };
    } else if (!hasStrongResume && careerContext?.githubScore > 70) {
      return {
        status: "Great coding activity, but resume is poorly optimized for ATS.",
        action: "Update your resume to fix keyword gaps."
      };
    } else if (skillsToImprove.length > 2) {
      return {
        status: `Missing foundational skills for ${careerContext?.targetRole || 'Software Engineering'} roles.`,
        action: `Complete learning paths for ${skillsToImprove[0]} and ${skillsToImprove[1]}.`
      };
    }

    return {
      status: "Steady progress towards target role readiness.",
      action: resumeNextAction || "Complete a mock interview session."
    };
  };

  const { status, action } = getStatusInfo();

  return (
    <motion.div 
      initial={{ opacity: 0, scale: 0.98 }}
      animate={{ opacity: 1, scale: 1 }}
      transition={{ duration: 0.5 }}
      className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 lg:col-span-3 flex flex-col gap-6"
    >
      <div className="flex items-center justify-between border-b border-slate-100 pb-4">
        <div className="flex items-center gap-2">
          <Target size={20} className="text-blue-500" />
          <h2 className="text-lg font-bold text-slate-900">Career Insights</h2>
        </div>
        <button onClick={() => navigate('/dashboard')} className="text-xs font-bold text-blue-600 hover:text-blue-700 flex items-center gap-1">
          Action Plan <ChevronRight size={14} />
        </button>
      </div>

      {/* Metrics Row */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-slate-50 border border-slate-100 rounded-xl p-4 flex flex-col items-center text-center">
          <FileText size={16} className="text-slate-400 mb-2" />
          <p className="text-xl font-black text-slate-800">{atsScore || 0}%</p>
          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Resume Score</p>
        </div>
        <div className="bg-slate-50 border border-slate-100 rounded-xl p-4 flex flex-col items-center text-center">
          <Code size={16} className="text-slate-400 mb-2" />
          <p className="text-xl font-black text-slate-800">{careerContext?.githubScore || 0}/100</p>
          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">GitHub Status</p>
        </div>
        <div className="bg-slate-50 border border-slate-100 rounded-xl p-4 flex flex-col items-center text-center">
          <TrendingUp size={16} className="text-slate-400 mb-2" />
          <p className="text-xl font-black text-slate-800">{careerContext?.alignmentScore || 0}%</p>
          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Skill Coverage</p>
        </div>
        <div className="bg-slate-50 border border-slate-100 rounded-xl p-4 flex flex-col items-center text-center">
          <Briefcase size={16} className="text-slate-400 mb-2" />
          <p className="text-sm font-black text-slate-800 truncate w-full px-2" title={careerContext?.targetRole || 'Not Set'}>
            {careerContext?.targetRole || 'Not Set'}
          </p>
          <p className="text-[10px] font-bold text-slate-500 uppercase tracking-wider mt-1">Recommended Role</p>
        </div>
      </div>

      {/* Text Insights */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-2">
        <div>
          <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Current Status</h3>
          <p className="text-sm font-medium text-slate-700 bg-slate-50 p-3 rounded-lg border border-slate-100">
            {status}
          </p>
        </div>
        <div>
          <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Recommended Next Step</h3>
          <p className="text-sm font-bold text-blue-700 bg-blue-50/50 p-3 rounded-lg border border-blue-100">
            {action}
          </p>
        </div>
      </div>

      {/* Skills */}
      {skillsToImprove.length > 0 && (
        <div className="pt-2 border-t border-slate-100">
          <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-3">Top Skills to Improve</h3>
          <div className="flex flex-wrap gap-2">
            {skillsToImprove.map((skill, i) => (
              <span key={i} className="px-3 py-1.5 bg-slate-100 text-slate-600 text-xs font-bold rounded-md border border-slate-200">
                {skill}
              </span>
            ))}
          </div>
        </div>
      )}
    </motion.div>
  );
}

import React, { useEffect, useState } from 'react';
import { TrendingUp, CheckCircle2, ArrowRight, Sparkles } from 'lucide-react';
import { motion } from 'framer-motion';
import { useCareer } from '../../contexts/CareerContext';
import { useResumeInsights } from '../../hooks/useResumeInsights';
import { useNavigate } from 'react-router-dom';

export default function CareerGrowthForecastWidget() {
  const { careerContext } = useCareer();
  const { atsScore } = useResumeInsights();
  const navigate = useNavigate();

  const [currentReadiness, setCurrentReadiness] = useState(0);

  // Calculate mock current readiness
  const calcCurrent = Math.round(((atsScore || 20) * 0.4) + ((careerContext?.githubScore || 0) * 0.3) + 20);
  const potentialReadiness = Math.min(100, calcCurrent + 35); // Simple mock calculation

  useEffect(() => {
    // Animate up to the calcCurrent
    const timer = setTimeout(() => setCurrentReadiness(calcCurrent), 100);
    return () => clearTimeout(timer);
  }, [calcCurrent]);

  const actionSteps = [
    { text: 'Complete 2 target projects', path: '/dashboard/projects' },
    { text: 'Close 4 priority skill gaps', path: '/dashboard/skills' },
    { text: 'Complete mock interview prep', path: '/dashboard/interview' },
    { text: 'Improve GitHub profile score', path: '/dashboard/github' }
  ];

  return (
    <motion.div 
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: 0.2 }}
      className="bg-gradient-to-br from-slate-900 to-slate-800 rounded-[24px] border border-slate-700 shadow-xl p-6 relative overflow-hidden text-white h-full flex flex-col"
    >
      {/* Decorative background grid/blur */}
      <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-10 mix-blend-overlay pointer-events-none"></div>
      <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/20 rounded-full blur-3xl pointer-events-none -translate-y-1/2 translate-x-1/3"></div>

      <div className="relative z-10 flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-indigo-500/20 flex items-center justify-center border border-indigo-400/30">
            <TrendingUp size={20} className="text-indigo-400" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-white flex items-center gap-2">
              Growth Forecast
              <Sparkles size={12} className="text-amber-400" />
            </h3>
            <p className="text-xs text-slate-400 font-medium mt-0.5">Predictive AI projection</p>
          </div>
        </div>
      </div>

      <div className="relative z-10 flex gap-4 mb-8">
        <div className="flex-1 bg-white/5 rounded-2xl p-4 border border-white/10">
          <span className="text-xs text-slate-400 font-bold uppercase tracking-wider block mb-1">Current Readiness</span>
          <div className="flex items-baseline gap-1">
            <span className="text-3xl font-black text-white">{currentReadiness}</span>
            <span className="text-sm text-slate-400 font-bold">%</span>
          </div>
        </div>
        <div className="flex items-center justify-center text-slate-500">
          <ArrowRight size={24} className="animate-pulse" />
        </div>
        <div className="flex-1 bg-indigo-500/10 rounded-2xl p-4 border border-indigo-500/20 relative overflow-hidden">
          <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/5 to-transparent -translate-x-full animate-[shimmer_2s_infinite]"></div>
          <span className="text-xs text-indigo-300 font-bold uppercase tracking-wider block mb-1">Potential Peak</span>
          <div className="flex items-baseline gap-1">
            <span className="text-3xl font-black text-indigo-400">{potentialReadiness}</span>
            <span className="text-sm text-indigo-500 font-bold">%</span>
          </div>
        </div>
      </div>

      <div className="relative z-10 flex-1 flex flex-col gap-1">
        <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">To reach this peak:</h4>
        <div className="space-y-2.5">
          {actionSteps.map((step, idx) => (
            <motion.div 
              key={idx}
              whileHover={{ x: 4, backgroundColor: 'rgba(255,255,255,0.1)' }}
              onClick={() => navigate(step.path)}
              className="flex items-center gap-3 p-2.5 rounded-xl bg-white/5 border border-white/5 hover:border-indigo-400/30 transition-all cursor-pointer group"
            >
              <CheckCircle2 size={16} className="text-emerald-400 shrink-0" />
              <span className="text-sm font-medium text-slate-200 flex-1">{step.text}</span>
              <ArrowRight size={14} className="text-slate-500 group-hover:text-indigo-400 transition-colors opacity-0 group-hover:opacity-100" />
            </motion.div>
          ))}
        </div>
      </div>
    </motion.div>
  );
}

import React from 'react';
import { Milestone, FileText, Code2, BrainCircuit, Play, Briefcase, Map } from 'lucide-react';
import { motion } from 'framer-motion';
import { useCareer } from '../../contexts/CareerContext';
import { useResumeInsights } from '../../hooks/useResumeInsights';

export default function CareerGrowthTimeline() {
  const { careerContext } = useCareer();
  const { hasInsights } = useResumeInsights();

  const hasGithub = careerContext?.githubScore > 0;

  const timelineEvents = [
    {
      id: 1,
      title: 'Profile Created',
      date: 'Aug 15, 2025',
      description: 'Joined OpportunityOS.',
      icon: Milestone,
      color: 'bg-emerald-500',
      done: true
    },
    {
      id: 2,
      title: 'Resume Analyzed',
      date: hasInsights ? 'Recent' : 'Pending',
      description: hasInsights ? 'ATS scoring and keyword extraction completed.' : 'Upload your resume for AI review.',
      icon: FileText,
      color: hasInsights ? 'bg-indigo-500' : 'bg-slate-300',
      done: hasInsights
    },
    {
      id: 3,
      title: 'GitHub Connected',
      date: hasGithub ? 'Recent' : 'Pending',
      description: hasGithub ? 'Analyzed project portfolio and tech stack.' : 'Link GitHub for code analysis.',
      icon: Code2,
      color: hasGithub ? 'bg-[#24292e]' : 'bg-slate-300',
      done: hasGithub
    },
    {
      id: 4,
      title: 'Skill Gap Generated',
      date: (hasInsights || hasGithub) ? 'Recent' : 'Pending',
      description: 'Personalized skill mapping created.',
      icon: BrainCircuit,
      color: (hasInsights || hasGithub) ? 'bg-blue-500' : 'bg-slate-300',
      done: (hasInsights || hasGithub)
    },
    {
      id: 5,
      title: 'Project Recommendations Generated',
      date: 'Pending',
      description: 'Curated projects to close skill gaps.',
      icon: Briefcase,
      color: 'bg-slate-300',
      done: false
    },
    {
      id: 6,
      title: 'Interview Prep Pending',
      date: 'Pending',
      description: 'Mock interviews based on target role.',
      icon: Play,
      color: 'bg-slate-300',
      done: false
    },
    {
      id: 7,
      title: 'Career Roadmap Pending',
      date: 'Pending',
      description: 'Your ultimate path to your dream job.',
      icon: Map,
      color: 'bg-slate-300',
      done: false
    }
  ];

  return (
    <motion.div 
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: 0.3 }}
      className="bg-white rounded-[24px] border border-slate-100 shadow-sm p-6 lg:col-span-2 hover:shadow-md transition-shadow h-full"
    >
      <div className="flex items-center gap-3 mb-8">
        <div className="w-10 h-10 rounded-xl bg-slate-50 flex items-center justify-center shrink-0">
          <Milestone size={20} className="text-slate-600" />
        </div>
        <div>
          <h3 className="text-sm font-bold text-slate-800">Career Trajectory</h3>
          <p className="text-xs text-slate-500 font-medium mt-0.5">Your progression milestones</p>
        </div>
      </div>

      <div className="relative pl-3">
        <div className="absolute left-[27px] top-4 bottom-4 w-0.5 bg-slate-100"></div>
        <div className="space-y-6">
          {timelineEvents.map((event, idx) => {
            const Icon = event.icon;
            return (
              <motion.div 
                key={event.id} 
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.4 + (idx * 0.1) }}
                className="relative flex gap-5"
              >
                <div className={`relative z-10 w-10 h-10 rounded-full flex items-center justify-center shrink-0 text-white shadow-sm ring-4 ring-white ${event.color}`}>
                  <Icon size={18} />
                </div>
                <div className={`flex-1 pt-1 ${!event.done && 'opacity-60'}`}>
                  <div className="flex flex-col sm:flex-row sm:justify-between sm:items-baseline gap-1 mb-1">
                    <h4 className="text-sm font-bold text-slate-800">{event.title}</h4>
                    <span className="text-[11px] font-bold text-slate-400">{event.date}</span>
                  </div>
                  <p className="text-xs text-slate-500 font-medium">{event.description}</p>
                </div>
              </motion.div>
            );
          })}
        </div>
      </div>
    </motion.div>
  );
}

import React from 'react';
import { Target, CheckCircle2, Circle, ArrowRight } from 'lucide-react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { useCareer } from '../../contexts/CareerContext';

export default function ImprovementTrackerWidget() {
  const navigate = useNavigate();
  const { careerContext } = useCareer();

  const goals = [
    { title: 'Update Resume Summary', category: 'ATS Optimization', status: 'done', path: '/dashboard/resume' },
    { title: 'Learn ' + (careerContext?.missingSkills?.[0] || 'System Design'), category: 'Skill Acquisition', status: 'in-progress', path: '/dashboard/skills' },
    { title: 'Complete Mock Interview', category: 'Interview Prep', status: 'pending', path: '/dashboard/interview' },
    { title: 'Add 2 Projects to GitHub', category: 'Portfolio', status: 'pending', path: '/dashboard/projects' }
  ];

  return (
    <motion.div 
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: 0.2 }}
      className="card-standard card-hover p-6 flex flex-col h-full"
    >
      <div className="flex items-center gap-3 mb-6">
        <div className="w-10 h-10 rounded-xl bg-orange-50 flex items-center justify-center shrink-0">
          <Target size={20} className="text-orange-600" />
        </div>
        <div>
          <h3 className="text-sm font-bold text-slate-800">Action Plan</h3>
          <p className="text-xs text-slate-500 font-medium mt-0.5">Short-term growth objectives</p>
        </div>
      </div>

      <div className="flex flex-col gap-3 flex-1 justify-center">
        {goals.map((goal, idx) => (
          <motion.div 
            key={idx}
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.3 + (idx * 0.1) }}
            onClick={() => goal.path && navigate(goal.path)}
            className={`flex items-start gap-3 p-3 rounded-xl transition-colors group ${goal.path ? 'hover:bg-slate-50 cursor-pointer' : ''}`}
          >
            <div className="mt-0.5 shrink-0">
              {goal.status === 'done' ? (
                <CheckCircle2 size={16} className="text-emerald-500" />
              ) : goal.status === 'in-progress' ? (
                <div className="w-4 h-4 rounded-full border-2 border-orange-500 border-t-transparent animate-spin" />
              ) : (
                <Circle size={16} className="text-slate-300 group-hover:border-indigo-400 transition-colors" />
              )}
            </div>
            <div className="flex-1">
              <h4 className={`text-sm font-bold ${goal.status === 'done' ? 'text-slate-400 line-through' : 'text-slate-700'}`}>
                {goal.title}
              </h4>
              <p className="text-[11px] font-medium text-slate-400 mt-0.5">{goal.category}</p>
            </div>
            {goal.status !== 'done' && goal.path && (
              <button className="opacity-0 group-hover:opacity-100 transition-opacity p-1.5 hover:bg-white rounded-lg text-slate-400 hover:text-indigo-600 shadow-sm border border-transparent hover:border-slate-200">
                <ArrowRight size={14} />
              </button>
            )}
          </motion.div>
        ))}
      </div>
    </motion.div>
  );
}

import React from 'react';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, ResponsiveContainer, Tooltip } from 'recharts';
import { Activity } from 'lucide-react';
import { motion } from 'framer-motion';
import { useCareer } from '../../contexts/CareerContext';
import { useResumeInsights } from '../../hooks/useResumeInsights';

export default function PlatformAnalysisRadar() {
  const { careerContext } = useCareer();
  const { atsScore } = useResumeInsights();

  const githubScore = careerContext?.githubScore || 0;
  // If no linkedin completeness is available, derive it roughly or set default
  const linkedinScore = careerContext?.linkedinScore || 0; 
  const alignmentScore = careerContext?.alignmentScore || 0;

  // Calculate proxy metrics
  const missingCount = careerContext?.missingSkills?.length || 5;
  const skillsScore = Math.max(0, 100 - (missingCount * 10)); // Simple proxy metric
  const projectScore = careerContext?.githubScore > 50 ? 80 : 40; // Proxy for projects
  const interviewScore = 30; // Proxy for interview prep
  const progressScore = Math.round((Math.max(0, 12 - missingCount) / 12) * 100) || 15; // Skill Gap Progress

  const data = [
    { subject: 'Resume', A: atsScore || 20, fullMark: 100 },
    { subject: 'GitHub', A: githubScore || 20, fullMark: 100 },
    { subject: 'Projects', A: projectScore, fullMark: 100 },
    { subject: 'Interview Prep', A: interviewScore, fullMark: 100 },
    { subject: 'Skill Progress', A: progressScore, fullMark: 100 },
    { subject: 'LinkedIn', A: linkedinScore || 20, fullMark: 100 },
    { subject: 'Alignment', A: alignmentScore || 20, fullMark: 100 },
    { subject: 'Tech Skills', A: skillsScore, fullMark: 100 },
  ];

  return (
    <motion.div 
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: 0.1 }}
      className="bg-white rounded-[24px] border border-slate-100 shadow-sm p-6 flex flex-col h-full hover:shadow-md transition-shadow"
    >
      <div className="flex items-center gap-3 mb-6">
        <div className="w-10 h-10 rounded-xl bg-blue-50 flex items-center justify-center shrink-0">
          <Activity size={20} className="text-blue-600" />
        </div>
        <div>
          <h3 className="text-sm font-bold text-slate-800">Platform Presence</h3>
          <p className="text-xs text-slate-500 font-medium mt-0.5">Cross-platform strength analysis</p>
        </div>
      </div>

      <div className="flex-1 w-full min-h-[250px] relative -mt-4">
        <ResponsiveContainer width="100%" height="100%">
          <RadarChart cx="50%" cy="50%" outerRadius="70%" data={data}>
            <PolarGrid stroke="#e2e8f0" />
            <PolarAngleAxis 
              dataKey="subject" 
              tick={{ fill: '#64748b', fontSize: 11, fontWeight: 600 }}
            />
            <PolarRadiusAxis angle={30} domain={[0, 100]} tick={false} axisLine={false} />
            <Tooltip 
              contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 20px rgba(0,0,0,0.08)' }}
              itemStyle={{ color: '#4f46e5', fontWeight: 'bold' }}
            />
            <Radar
              name="Score"
              dataKey="A"
              stroke="#6366f1"
              strokeWidth={2}
              fill="#818cf8"
              fillOpacity={0.3}
              isAnimationActive={true}
              animationBegin={200}
              animationDuration={1500}
              animationEasing="ease-out"
            />
          </RadarChart>
        </ResponsiveContainer>
      </div>
    </motion.div>
  );
}

import React, { useMemo } from 'react';
import { AlertCircle, Code, Server, LayoutTemplate, Shield, Database, Cpu } from 'lucide-react';
import { motion } from 'framer-motion';
import { useCareer } from '../../contexts/CareerContext';

export default function TopMissingSkillsWidget() {
  const { careerContext } = useCareer();
  const targetRole = careerContext?.targetRole || 'Software Engineer';

  // Role-specific mock data generator
  const generatedSkills = useMemo(() => {
    if (careerContext?.missingSkills && careerContext.missingSkills.length > 0) {
      return careerContext.missingSkills;
    }

    const roleMap = {
      'AI Engineer': ['RAG', 'Vector Databases', 'MLOps', 'Docker'],
      'Software Engineer': ['System Design', 'Testing', 'API Design', 'Scalability'],
      'Cyber Security': ['Threat Detection', 'SIEM', 'Penetration Testing', 'Network Auth'],
      'Data Scientist': ['Spark', 'PyTorch', 'Data Pipelines', 'A/B Testing']
    };

    // Find closest match or default
    const matchedRole = Object.keys(roleMap).find(r => targetRole.toLowerCase().includes(r.toLowerCase()));
    return roleMap[matchedRole] || roleMap['Software Engineer'];
  }, [careerContext?.missingSkills, targetRole]);

  const missingSkills = generatedSkills;

  const getIconForSkill = (skill) => {
    const s = skill.toLowerCase();
    if (s.includes('react') || s.includes('css') || s.includes('ui')) return <LayoutTemplate size={14} className="text-pink-500" />;
    if (s.includes('node') || s.includes('sql') || s.includes('api') || s.includes('server')) return <Server size={14} className="text-emerald-500" />;
    if (s.includes('threat') || s.includes('security') || s.includes('siem') || s.includes('auth')) return <Shield size={14} className="text-red-500" />;
    if (s.includes('data') || s.includes('vector') || s.includes('spark')) return <Database size={14} className="text-blue-500" />;
    if (s.includes('ml') || s.includes('rag') || s.includes('ai') || s.includes('torch')) return <Cpu size={14} className="text-purple-500" />;
    return <Code size={14} className="text-indigo-500" />;
  };

  return (
    <motion.div 
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: 0.2 }}
      className="bg-white rounded-[24px] border border-slate-100 shadow-sm p-6 hover:shadow-md transition-shadow h-full flex flex-col"
    >
      <div className="flex items-center gap-3 mb-5">
        <div className="w-10 h-10 rounded-xl bg-rose-50 flex items-center justify-center shrink-0">
          <AlertCircle size={20} className="text-rose-600" />
        </div>
        <div>
          <h3 className="text-sm font-bold text-slate-800">Priority Missing Skills</h3>
          <p className="text-xs text-slate-500 font-medium mt-0.5">Identified from market analysis</p>
        </div>
      </div>

      <div className="flex-1 flex flex-col justify-center gap-3 mt-2">
        {missingSkills.slice(0, 4).map((skill, index) => (
          <motion.div 
            key={index} 
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.3 + (index * 0.1) }}
            whileHover={{ scale: 1.02 }}
            className="flex items-center justify-between p-3 rounded-xl bg-slate-50 border border-slate-100 hover:bg-slate-100 transition-all cursor-default"
          >
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-lg bg-white shadow-sm flex items-center justify-center border border-slate-100">
                {getIconForSkill(skill)}
              </div>
              <span className="text-sm font-bold text-slate-700">{skill}</span>
            </div>
            <span className="text-[10px] font-bold px-2 py-1 bg-white border border-slate-200 rounded-md text-slate-500 uppercase">
              High Priority
            </span>
          </motion.div>
        ))}
        {missingSkills.length === 0 && (
          <div className="text-center p-4 bg-emerald-50 rounded-xl border border-emerald-100">
            <p className="text-sm font-bold text-emerald-700">No critical missing skills!</p>
            <p className="text-xs text-emerald-600 mt-1">Your profile perfectly aligns with your target role.</p>
          </div>
        )}
      </div>
    </motion.div>
  );
}

import { ErrorBoundary } from 'react-error-boundary';
import { AlertTriangle, RefreshCw, Home } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { analyticsService } from '../../services/analyticsService';


function FallbackUI({ error, resetErrorBoundary, type = 'global' }) {
  const handleReload = () => {
    window.location.reload();
  };

  const isWidget = type === 'widget';
  const isRoute = type === 'route';

  return (
    <div className={`flex flex-col items-center justify-center p-6 text-center ${
      isWidget ? 'h-full min-h-[200px] bg-slate-50 border border-slate-200 rounded-2xl' : 'min-h-[60vh]'
    }`}>
      <div className={`flex items-center justify-center rounded-full bg-red-50 text-red-500 mb-4 ${
        isWidget ? 'w-12 h-12' : 'w-16 h-16'
      }`}>
        <AlertTriangle size={isWidget ? 24 : 32} />
      </div>

      <h2 className={`${isWidget ? 'text-[16px]' : 'text-[20px]'} font-extrabold text-slate-900 mb-2`}>
        {isWidget ? 'Widget unavailable' : 'Something went wrong.'}
      </h2>

      <p className="text-[13px] text-slate-500 max-w-md mx-auto mb-6">
        {error?.message || 'An unexpected error occurred while rendering this component.'}
      </p>

      <div className="flex items-center gap-3">
        <button
          onClick={resetErrorBoundary}
          className="flex items-center gap-2 px-4 py-2 bg-[#6C4CF1] hover:bg-[#5b3fda] text-white text-[13px] font-bold rounded-xl transition-all shadow-sm"
        >
          <RefreshCw size={14} />
          Retry
        </button>

        {!isWidget && (
          <button
            onClick={handleReload}
            className="flex items-center gap-2 px-4 py-2 bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 text-[13px] font-bold rounded-xl transition-all shadow-sm"
          >
            <Home size={14} />
            Reload Page
          </button>
        )}
      </div>
    </div>
  );
}

export function GlobalErrorBoundary({ children }) {
  return (
    <ErrorBoundary
      FallbackComponent={(props) => <FallbackUI {...props} type="global" />}
      onError={(error, info) => {
        console.error('Global Crash Detected:', error);
        console.error('Component Stack:', info.componentStack);
        analyticsService.trackError('UI_CRASH_GLOBAL', error);
      }}
    >
      {children}
    </ErrorBoundary>
  );
}

export function RouteErrorBoundary({ children }) {
  return (
    <ErrorBoundary
      FallbackComponent={(props) => <FallbackUI {...props} type="route" />}
      onError={(error, info) => {
        console.error('Route Crash Detected:', error);
        console.error('Component Stack:', info.componentStack);
        analyticsService.trackError('UI_CRASH_ROUTE', error);
      }}
    >
      {children}
    </ErrorBoundary>
  );
}

export function WidgetErrorBoundary({ children }) {
  return (
    <ErrorBoundary
      FallbackComponent={(props) => <FallbackUI {...props} type="widget" />}
      onError={(error, info) => {
        console.error('Widget Crash Detected:', error);
        console.error('Component Stack:', info.componentStack);
        analyticsService.trackError('UI_CRASH_WIDGET', error);
      }}
    >
      {children}
    </ErrorBoundary>
  );
}

import { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import { Wifi, WifiOff } from 'lucide-react';

export default function NetworkStatusManager() {
  const [isOnline, setIsOnline] = useState(navigator.onLine);


  useEffect(() => {
    const handleOnline = () => {
      setIsOnline(true);
      toast.success('You are back online!', {
        icon: <Wifi className="text-emerald-500" size={18} />,
        duration: 4000,
      });
    };

    const handleOffline = () => {
      setIsOnline(false);
      toast.error('You are offline. Some features may be unavailable.', {
        icon: <WifiOff className="text-red-500" size={18} />,
        duration: Infinity, // Keep showing until they come back online
        id: 'offline-toast', // Unique ID to avoid duplicates and allow programmatic dismissal
      });
    };

    // If starting offline, show the toast immediately
    if (!navigator.onLine) {
      handleOffline();
    }

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      toast.dismiss('offline-toast');
    };
  }, []);

  return null; // This is a logic-only component
}

