export const SelectionGrid = ({ options, selectedValue, onSelect, columns = 2, themeColor = 'blue' }) => {
  const themeStyles = {
    blue: 'border-blue-500 bg-blue-50 text-blue-700',
    purple: 'border-purple-500 bg-purple-50 text-purple-700',
    pink: 'border-pink-500 bg-pink-50 text-pink-700',
    orange: 'border-orange-500 bg-orange-50 text-orange-700',
    green: 'border-emerald-500 bg-emerald-50 text-emerald-700',
  };

  const activeStyle = themeStyles[themeColor] || themeStyles.blue;

  return (
    <div className={`grid gap-3 w-full`} style={{ gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` }}>
      {options.map((opt) => {
        const isSelected = selectedValue === opt.value || selectedValue === opt.label || selectedValue === opt;
        const val = typeof opt === 'string' ? opt : opt.value;
        const label = typeof opt === 'string' ? opt : opt.label;
        const Icon = opt.icon;

        return (
          <motion.button
            whileHover={{ scale: 1.03, y: -2 }}
            whileTap={{ scale: 0.98 }}
            key={val}
            onClick={() => onSelect(val)}
            className={`
              relative flex flex-col items-center justify-center p-4 rounded-2xl border-2 transition-all duration-300 text-center
              ${isSelected 
                ? `${activeStyle} shadow-md` 
                : 'border-slate-100 bg-white hover:border-slate-200 hover:shadow text-slate-600'}
            `}
          >
            {Icon && <Icon size={24} className={`mb-2 ${isSelected ? '' : 'text-slate-400'}`} />}
            <span className="font-semibold text-sm">{label}</span>

            {isSelected && (
              <motion.div 
                initial={{ scale: 0 }} 
                animate={{ scale: 1 }} 
                className={`absolute -top-2 -right-2 w-6 h-6 rounded-full flex items-center justify-center text-white ${activeStyle.split(' ')[0].replace('border', 'bg')}`}
              >
                <Check size={14} strokeWidth={3} />
              </motion.div>
            )}
          </motion.button>
        );
      })}
    </div>
  );
};

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowRight, ArrowLeft } from 'lucide-react';

export default function QuestionRenderer({ 
  children, 
  title, 
  subtitle, 
  icon: Icon,
  onNext, 
  onBack, 
  canGoNext, 
  themeColor = 'blue' 
}) {

  const themeColors = {
    blue: 'from-blue-600 to-cyan-500 hover:from-blue-500 hover:to-cyan-400',
    purple: 'from-purple-600 to-fuchsia-500 hover:from-purple-500 hover:to-fuchsia-400',
    pink: 'from-pink-600 to-rose-500 hover:from-pink-500 hover:to-rose-400',
    orange: 'from-orange-600 to-amber-500 hover:from-orange-500 hover:to-amber-400',
    green: 'from-emerald-600 to-teal-500 hover:from-emerald-500 hover:to-teal-400',
  };

  const bgGradient = themeColors[themeColor] || themeColors.blue;

  return (
    <div className="flex flex-col h-full w-full relative p-6 sm:p-10 z-10 overflow-hidden">

      {/* Question Content with Animation */}
      <div className="flex-1 flex flex-col justify-center max-w-[500px] w-full mx-auto relative mt-4 mb-24">
        <AnimatePresence mode="wait">
          <motion.div
            key={title} // Animates when title changes (new question)
            initial={{ opacity: 0, x: 20, scale: 0.98 }}
            animate={{ opacity: 1, x: 0, scale: 1 }}
            exit={{ opacity: 0, x: -20, scale: 0.98 }}
            transition={{ duration: 0.4, ease: [0.22, 1, 0.36, 1] }}
            className="flex flex-col w-full"
          >
            <div className="text-center mb-10">
              {Icon && (
                <div className="mx-auto w-16 h-16 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-center mb-6 shadow-sm">
                  <Icon size={32} className={`text-${themeColor}-500`} />
                </div>
              )}
              <h2 className="text-3xl font-bold text-slate-900 tracking-tight mb-3">{title}</h2>
              {subtitle && <p className="text-base text-slate-500 font-medium">{subtitle}</p>}
            </div>

            <div className="w-full">
              {children}
            </div>
          </motion.div>
        </AnimatePresence>
      </div>

      {/* Fixed Bottom Navigation */}
      <div className="absolute bottom-0 left-0 right-0 p-6 sm:p-8 bg-gradient-to-t from-white via-white to-transparent pointer-events-none flex justify-center">
