import { useState, useEffect, useRef } from 'react';
import { Target, ChevronRight, Code, Bot, BarChart2, Layers, ShieldCheck, Cloud, Infinity, Briefcase, Plus, CheckCircle2, Edit2 } from 'lucide-react';
import { useGoals } from '../../contexts/GoalContext';

const ROLES = [
  { id: 'Software Engineer', title: 'Software Engineer', desc: 'Design, build and maintain scalable software systems.', icon: Code, color: 'text-[#6C4CF1]', bg: 'bg-[#F4F1FE]' },
  { id: 'AI Engineer', title: 'AI Engineer', desc: 'Build intelligent systems using ML, NLP and GenAI.', icon: Bot, color: 'text-[#6C4CF1]', bg: 'bg-[#F4F1FE]' },
  { id: 'Data Scientist', title: 'Data Scientist', desc: 'Extract insights from data and build predictive models.', icon: BarChart2, color: 'text-[#6C4CF1]', bg: 'bg-[#F4F1FE]' },
  { id: 'Full Stack Developer', title: 'Full Stack Developer', desc: 'Work on frontend, backend and databases.', icon: Layers, color: 'text-[#10B981]', bg: 'bg-emerald-50' },
  { id: 'Cyber Security Engineer', title: 'Cyber Security Engineer', desc: 'Protect systems and data from cyber threats.', icon: ShieldCheck, color: 'text-[#EF4444]', bg: 'bg-red-50' },
  { id: 'Cloud Engineer', title: 'Cloud Engineer', desc: 'Design and manage secure cloud infrastructure.', icon: Cloud, color: 'text-[#0EA5E9]', bg: 'bg-sky-50' },
  { id: 'DevOps Engineer', title: 'DevOps Engineer', desc: 'Automate, deploy and scale applications seamlessly.', icon: Infinity, color: 'text-[#F59E0B]', bg: 'bg-amber-50' },
  { id: 'Product Manager', title: 'Product Manager', desc: 'Lead product strategy and build user-centric solutions.', icon: Briefcase, color: 'text-[#8B5CF6]', bg: 'bg-purple-50' },
  { id: 'other', title: 'Other / Custom Role', desc: 'Define a custom role and get a tailored analysis.', icon: Plus, color: 'text-slate-500', bg: 'bg-slate-100' },
];

export default function Step1TargetRole({ onSubmit, initialRole }) {
  const { goals } = useGoals();
  const [role, setRole] = useState(initialRole || '');
  const [customRole, setCustomRole] = useState('');
  const customInputRef = useRef(null);

  useEffect(() => {
    if (!initialRole && goals && goals.length > 0) {
      const activeGoal = goals.find(g => g.isActive) || goals[0];
      if (activeGoal && activeGoal.targetCareer) {
        if (ROLES.some(r => r.id === activeGoal.targetCareer)) {
          setRole(activeGoal.targetCareer);
        } else {
          setRole('other');
          setCustomRole(activeGoal.targetCareer);
        }
      }
    }
  }, [initialRole, goals]);

  const handleRoleSelect = (id) => {
    if (id === 'other') {
      setRole('other');
      setTimeout(() => customInputRef.current?.focus(), 50);
    } else {
      setRole(id);
      setCustomRole('');
    }
  };

  const handleCustomRoleChange = (e) => {
    setCustomRole(e.target.value);
    setRole('other');
  };

  const handleSubmit = (e) => {
    e?.preventDefault();
    const finalRole = role === 'other' ? customRole.trim() : role.trim();
    if (finalRole) {
      onSubmit(finalRole);
    }
  };

  const activeRoleText = role === 'other' ? customRole : role;
  const canContinue = activeRoleText && activeRoleText.trim().length > 0;

  return (
    <div className="w-full max-w-[900px] bg-white rounded-3xl border border-slate-100 shadow-[0_8px_30px_rgb(0,0,0,0.04)] overflow-hidden animate-in fade-in zoom-in-95 duration-500 flex flex-col">
      <div className="pt-6 px-6 lg:px-8 pb-0">

        {/* Top Section */}
        <div className="flex flex-col items-center text-center mb-5">
          <div className="w-10 h-10 bg-[#F8F6FE] rounded-xl flex items-center justify-center mb-3 border border-[#E9E4FC] shadow-sm">
            <Target size={20} className="text-[#6C4CF1]" />
          </div>
          <h1 className="text-xl lg:text-2xl font-black text-slate-900 mb-1 tracking-tight">What role are you preparing for?</h1>
          <p className="text-slate-500 font-medium text-[13px] max-w-xl">
            Select the career you're aiming for. We'll analyze your current skills and identify the gaps.
          </p>
        </div>

        {/* Roles Grid */}
        <div className="mb-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-2">
            {ROLES.map((r) => {
              const isSelected = role === r.id;
              const Icon = r.icon;
              return (
                <div
                  key={r.id}
                  onClick={() => handleRoleSelect(r.id)}
                  className={`relative p-3 rounded-xl border-2 transition-all cursor-pointer group flex flex-col min-h-[90px] ${
                    isSelected 
                      ? 'border-[#6C4CF1] bg-[#F8F6FE] shadow-[0_4px_12px_-4px_rgba(108,76,241,0.12)]' 
                      : 'border-slate-100 bg-white hover:border-slate-200 hover:bg-slate-50/50'
                  }`}
                >
                  <div className="absolute top-3 right-3">
                    {isSelected ? (
                      <div className="w-4 h-4 rounded-full bg-[#6C4CF1] flex items-center justify-center shadow-sm">
                        <CheckCircle2 size={10} className="text-white" />
                      </div>
                    ) : (
                      <div className="w-4 h-4 rounded-full border-2 border-slate-200 group-hover:border-slate-300 transition-colors" />
                    )}
                  </div>

                  <div className={`w-8 h-8 rounded-lg flex items-center justify-center mb-2 ${r.bg}`}>
                    <Icon size={16} className={r.color} />
                  </div>
                  <h3 className="font-bold text-slate-900 text-[13px] mb-0.5">{r.title}</h3>
                  <p className="text-[11px] text-slate-500 font-medium leading-tight pr-4 line-clamp-2">{r.desc}</p>
                </div>
              );
            })}
          </div>
        </div>

        {/* OR Divider */}
        <div className="flex items-center justify-center py-1 mb-3">
          <div className="h-px bg-slate-100 flex-1" />
          <span className="px-3 text-[9px] font-black text-slate-400 uppercase tracking-widest">OR</span>
          <div className="h-px bg-slate-100 flex-1" />
        </div>

        {/* Custom Role Input */}
        <div 
          onClick={() => {
            setRole('other');
            customInputRef.current?.focus();
          }}
          className={`flex items-center gap-3 p-3 rounded-xl border-2 transition-all cursor-text mb-6 ${
            role === 'other'
              ? 'border-[#6C4CF1] bg-[#F8F6FE] shadow-[0_4px_12px_-4px_rgba(108,76,241,0.12)]'
              : 'border-slate-100 bg-white hover:border-slate-200 hover:bg-slate-50/50'
          }`}
        >
          <div className="w-8 h-8 rounded-lg bg-[#F8F6FE] flex items-center justify-center shrink-0">
            <Edit2 size={16} className="text-[#6C4CF1]" />
          </div>
          <div className="flex-1 flex flex-col sm:flex-row sm:items-center gap-2 sm:gap-4">
            <div className="min-w-[140px]">
              <h3 className="font-bold text-slate-900 text-[13px]">Can't find your role?</h3>
              <p className="text-[11px] text-slate-500 font-medium">Enter target role here.</p>
            </div>
            <input
              ref={customInputRef}
              type="text"
              value={customRole}
              onChange={handleCustomRoleChange}
              placeholder="e.g. Robotics Engineer"
              className={`flex-1 w-full px-3 py-2 rounded-lg border text-[13px] font-semibold outline-none transition-all placeholder:font-medium placeholder:text-slate-400 ${
                role === 'other'
                  ? 'bg-white border-[#6C4CF1]/30 shadow-sm focus:border-[#6C4CF1] focus:ring-2 focus:ring-[#6C4CF1]/10 text-slate-900'
                  : 'bg-white border-slate-200 text-slate-900'
              }`}
            />
          </div>
        </div>
      </div>

      {/* Bottom Sticky Selection Bar */}
      <div className="bg-[#F8F6FE] border-t border-[#E9E4FC] px-6 py-4 flex items-center justify-between mt-auto">
        <div className="flex flex-col">
          <span className="text-[11px] font-bold text-slate-400 uppercase tracking-wider mb-1">Selected Role</span>
          {activeRoleText ? (
            <div className="flex items-center gap-2">
              <div className="w-5 h-5 rounded-[6px] bg-[#6C4CF1] flex items-center justify-center">
                <Code size={10} className="text-white" />
              </div>
              <span className="font-black text-slate-900 text-[14px]">{activeRoleText}</span>
              <button 
                onClick={() => {
                  setRole('');
                  setCustomRole('');
                }}
                className="text-[11px] font-bold text-[#6C4CF1] hover:text-[#5a3bc2] transition-colors ml-2"
              >
                Change
              </button>
            </div>
          ) : (
            <span className="text-[14px] font-bold text-slate-400 italic">None selected</span>
          )}
        </div>

        <button
          onClick={handleSubmit}
          disabled={!canContinue}
          className="w-[220px] h-[52px] bg-[#6C4CF1] hover:bg-[#5A3BC2] disabled:bg-slate-300 disabled:cursor-not-allowed text-white rounded-[14px] font-semibold text-[16px] flex items-center justify-center gap-[10px] shadow-[0_4px_14px_rgba(108,76,241,0.39)] hover:shadow-[0_6px_20px_rgba(108,76,241,0.23)] hover:-translate-y-0.5 disabled:hover:translate-y-0 disabled:shadow-none transition-all duration-200 active:scale-[0.98] disabled:active:scale-100 overflow-visible"
        >
          Continue <ChevronRight size={18} className="text-white" strokeWidth={2.5} />
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { UploadCloud, GitBranch, Link as LinkIcon, ListPlus, ChevronLeft, ChevronRight, X, FileText, CheckCircle2 } from 'lucide-react';

export default function Step2bInputCollection({ sources, onSubmit, onBack, initialData = {} }) {
  const [resumeFile, setResumeFile] = useState(initialData.resumeFile || null);
  const [githubUrl, setGithubUrl] = useState(initialData.githubUrl || '');
  const [linkedinFile, setLinkedinFile] = useState(initialData.linkedinFile || null);
  const [manualSkills, setManualSkills] = useState(initialData.manualSkills || []);
  const [skillInput, setSkillInput] = useState('');

  const [isDragging, setIsDragging] = useState(false);
  const [isDraggingLinkedin, setIsDraggingLinkedin] = useState(false);
  const fileInputRef = useRef(null);
  const linkedinInputRef = useRef(null);

  const pendingSkills = skillInput.split(',').map(s => s.trim()).filter(s => s !== '');
  const allCurrentSkills = [...new Set([...manualSkills, ...pendingSkills])];

  // Validation
  const isValidGithub = !sources.includes('github') || (githubUrl.trim().length > 0 && githubUrl.includes('github.com/'));
  const isValidLinkedin = !sources.includes('linkedin') || linkedinFile !== null;
  const isValidResume = !sources.includes('resume') || resumeFile !== null;
  const isValidManual = !sources.includes('manual') || allCurrentSkills.length >= 3;

  const canContinue = isValidGithub && isValidLinkedin && isValidResume && isValidManual;

  const handleSubmit = () => {
    if (canContinue) {
      onSubmit({
        resumeFile,
        githubUrl,
        linkedinFile,
        manualSkills: allCurrentSkills
      });
    }
  };

  // Drag and Drop Handlers
  const handleDragOver = (e) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => {
    setIsDragging(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setIsDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const file = e.dataTransfer.files[0];
      if (file.type === 'application/pdf' || file.name.endsWith('.docx')) {
        setResumeFile(file);
      }
    }
  };

  const handleFileChange = (e) => {
    if (e.target.files && e.target.files.length > 0) {
      setResumeFile(e.target.files[0]);
    }
  };

  const handleDragOverLinkedin = (e) => {
    e.preventDefault();
    setIsDraggingLinkedin(true);
  };

  const handleDragLeaveLinkedin = () => {
    setIsDraggingLinkedin(false);
  };

  const handleDropLinkedin = (e) => {
    e.preventDefault();
    setIsDraggingLinkedin(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const file = e.dataTransfer.files[0];
      if (file.type === 'application/pdf') {
        setLinkedinFile(file);
      }
    }
  };

  const handleFileChangeLinkedin = (e) => {
    if (e.target.files && e.target.files.length > 0) {
      setLinkedinFile(e.target.files[0]);
    }
  };

  // Skill Input Handlers
  const handleAddSkill = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (pendingSkills.length > 0) {
        setManualSkills(allCurrentSkills);
        setSkillInput('');
      }
    }
  };

  const removeSkill = (skillToRemove) => {
    setManualSkills(manualSkills.filter(s => s !== skillToRemove));
  };

  return (
    <div className="w-full max-w-[900px] mx-auto bg-white rounded-2xl border border-slate-200 shadow-sm p-6 lg:p-8 animate-in fade-in slide-in-from-right-8 duration-500">
      <div className="flex flex-col items-center text-center mb-10">
        <h1 className="text-2xl lg:text-3xl font-black text-slate-900 mb-2">Provide Your Details</h1>
        <p className="text-slate-500 font-medium">We need a bit more information based on the sources you selected.</p>
      </div>

      <div className="space-y-6 mb-10">

        {/* Resume Input */}
        {sources.includes('resume') && (
          <div className="border border-slate-200 rounded-2xl p-6 bg-slate-50/50">
            <h3 className="font-bold text-slate-900 flex items-center gap-2 mb-4">
              <FileText className="text-blue-500" size={20} />
              Upload Resume <span className="text-red-500">*</span>
            </h3>

            {!resumeFile ? (
              <div 
                className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center transition-all cursor-pointer ${
                  isDragging ? 'border-blue-500 bg-blue-50' : 'border-slate-300 hover:border-slate-400 bg-white'
                }`}
                onDragOver={handleDragOver}
                onDragLeave={handleDragLeave}
                onDrop={handleDrop}
                onClick={() => fileInputRef.current?.click()}
              >
                <div className="w-12 h-12 rounded-full bg-blue-50 flex items-center justify-center mb-3">
                  <UploadCloud className="text-blue-500" size={24} />
                </div>
                <p className="font-bold text-slate-700 mb-1">Click to upload or drag and drop</p>
                <p className="text-sm text-slate-500 font-medium mb-2">PDF or DOCX (max 5MB)</p>
                {allCurrentSkills.length > 0 && (
                  <p className="text-[11px] font-bold text-indigo-500 bg-indigo-50 px-3 py-1 rounded-full border border-indigo-100">
                    Using {allCurrentSkills.length} profile skills. Upload a resume for better accuracy!
                  </p>
                )}
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  onChange={handleFileChange} 
                  accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" 
                  className="hidden" 
                />
              </div>
            ) : (
              <div className="flex items-center justify-between p-4 bg-white border border-slate-200 rounded-xl shadow-sm">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-lg bg-emerald-50 flex items-center justify-center">
                    <CheckCircle2 className="text-emerald-500" size={20} />
                  </div>
                  <div>
                    <p className="font-bold text-slate-900">{resumeFile.name}</p>
                    <p className="text-[12px] font-medium text-slate-500">{(resumeFile.size / 1024 / 1024).toFixed(2)} MB</p>
                  </div>
                </div>
                <button 
                  onClick={() => setResumeFile(null)}
                  className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                >
                  <X size={20} />
                </button>
              </div>
            )}
          </div>
        )}

        {/* GitHub Input */}
        {sources.includes('github') && (
          <div className="border border-slate-200 rounded-2xl p-6 bg-slate-50/50">
            <h3 className="font-bold text-slate-900 flex items-center gap-2 mb-4">
              <GitBranch className="text-slate-700" size={20} />
              GitHub Profile <span className="text-red-500">*</span>
            </h3>
            <input
              type="url"
              value={githubUrl}
              onChange={(e) => setGithubUrl(e.target.value)}
              placeholder="https://github.com/username"
              className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-[#6C4CF1]/50 font-medium text-slate-900 placeholder:text-slate-400"
            />
          </div>
        )}

        {/* LinkedIn Input */}
        {sources.includes('linkedin') && (
          <div className="border border-slate-200 rounded-2xl p-6 bg-slate-50/50">
            <h3 className="font-bold text-slate-900 flex items-center gap-2 mb-4">
              <LinkIcon className="text-sky-600" size={20} />
              LinkedIn Profile PDF <span className="text-red-500">*</span>
            </h3>

            {!linkedinFile ? (
              <div 
                className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center transition-all cursor-pointer ${
                  isDraggingLinkedin ? 'border-sky-500 bg-sky-50' : 'border-slate-300 hover:border-slate-400 bg-white'
                }`}
                onDragOver={handleDragOverLinkedin}
                onDragLeave={handleDragLeaveLinkedin}
                onDrop={handleDropLinkedin}
                onClick={() => linkedinInputRef.current?.click()}
              >
                <div className="w-12 h-12 rounded-full bg-sky-50 flex items-center justify-center mb-3">
                  <UploadCloud className="text-sky-600" size={24} />
                </div>
                <p className="font-bold text-slate-700 mb-1">Click to upload or drag and drop</p>
                <p className="text-sm text-slate-500 font-medium">PDF only (max 5MB)</p>
                <input 
                  type="file" 
                  ref={linkedinInputRef} 
                  onChange={handleFileChangeLinkedin} 
                  accept=".pdf,application/pdf" 
                  className="hidden" 
                />
              </div>
            ) : (
              <div className="flex items-center justify-between p-4 bg-white border border-slate-200 rounded-xl shadow-sm">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-lg bg-emerald-50 flex items-center justify-center">
                    <CheckCircle2 className="text-emerald-500" size={20} />
                  </div>
                  <div>
                    <p className="font-bold text-slate-900">{linkedinFile.name}</p>
                    <p className="text-[12px] font-medium text-slate-500">{(linkedinFile.size / 1024 / 1024).toFixed(2)} MB</p>
                  </div>
                </div>
                <button 
                  onClick={() => setLinkedinFile(null)}
                  className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
                >
                  <X size={20} />
                </button>
              </div>
            )}
          </div>
        )}

        {/* Manual Skills Input */}
        {sources.includes('manual') && (
          <div className="border border-slate-200 rounded-2xl p-6 bg-slate-50/50">
            <h3 className="font-bold text-slate-900 flex items-center justify-between gap-2 mb-4">
              <div className="flex items-center gap-2">
                <ListPlus className="text-purple-500" size={20} />
                Manual Skills <span className="text-red-500">*</span>
              </div>
              <span className={`text-[12px] font-bold px-2 py-1 rounded-md ${allCurrentSkills.length >= 3 ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>
                {allCurrentSkills.length >= 3 ? `${allCurrentSkills.length} Entered` : `${allCurrentSkills.length}/3 Required`}
              </span>
            </h3>
            <input
              type="text"
              value={skillInput}
              onChange={(e) => setSkillInput(e.target.value)}
              onKeyDown={handleAddSkill}
              placeholder="e.g. Python, React, Data Analysis"
              className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:outline-none focus:ring-2 focus:ring-[#6C4CF1]/50 font-medium text-slate-900 placeholder:text-slate-400 mb-4"
            />

            {manualSkills.length > 0 && (
              <div className="flex flex-wrap gap-2">
                {manualSkills.map((skill, index) => (
                  <div key={index} className="flex items-center gap-1.5 bg-white border border-slate-200 px-3 py-1.5 rounded-lg shadow-sm">
                    <span className="text-sm font-semibold text-slate-700">{skill}</span>
                    <button 
                      onClick={() => removeSkill(skill)}
                      className="text-slate-400 hover:text-red-500 transition-colors"
                    >
                      <X size={14} />
                    </button>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

      </div>

      <div className="flex items-center justify-between pt-8 mt-4 border-t border-slate-100">
        <button
          onClick={onBack}
          className="px-6 py-3 rounded-xl font-bold text-slate-500 hover:bg-slate-100 transition-colors flex items-center gap-2"
        >
          <ChevronLeft size={20} /> Back
        </button>
        <button
          onClick={handleSubmit}
          disabled={!canContinue}
          className="bg-[#6C4CF1] hover:bg-indigo-600 text-white font-bold rounded-xl px-8 py-3 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 shadow-sm hover:shadow-md"
        >
          Analyze Skills
          <ChevronRight size={20} color="#FFFFFF" />
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Bot, CheckCircle2, Loader2 } from 'lucide-react';
import { geminiService } from '../../services/geminiService';
import { fileToBase64 } from '../../utils/fileUtils';
import { toast } from 'react-hot-toast';

const STEPS = [
  "Extracting Skills from Sources...",
  "Analyzing GitHub & Resume Data...",
  "Comparing Against Industry Standards...",
  "Calculating Readiness Score...",
  "Building Personalized Learning Path..."
];

export default function Step3Analyzing({ targetRole, sources, inputData, onComplete }) {
  const [currentStepIndex, setCurrentStepIndex] = useState(0);

  useEffect(() => {
    let isMounted = true;

    async function performAnalysis() {
      try {
        // Step 0: Extracting Skills...
        setCurrentStepIndex(0);

        let resumeData = null;
        if (inputData?.resumeFile) {
          resumeData = await fileToBase64(inputData.resumeFile);
        }

        let linkedinData = null;
        if (inputData?.linkedinFile) {
          linkedinData = await fileToBase64(inputData.linkedinFile);
        }

        // Step 1: Analyzing GitHub...
        setCurrentStepIndex(1);

        let githubData = null;
        if (inputData?.githubUrl) {
          try {
            const match = inputData.githubUrl.match(/github\.com\/([^/]+)/);
            if (match && match[1]) {
              const username = match[1];
              const response = await fetch(`https://api.github.com/users/${username}/repos?per_page=10&sort=updated`);
              if (response.ok) {
                const repos = await response.json();
                githubData = repos.map(repo => ({
                  name: repo.name,
                  language: repo.language,
                  description: repo.description,
                  topics: repo.topics
                }));
              }
            }
          } catch (e) {
            console.warn("GitHub fetch failed", e);
          }
        }

        // Step 2 & 3: Comparing and Calculating (Handled by Gemini AI call)
        setCurrentStepIndex(2);

        const payload = {
          targetRole,
          manualSkills: inputData?.manualSkills || [],
          githubData,
          linkedinData,
          resumeData
        };

        // Let the UI show step 3 after a tiny delay so it doesn't get skipped visually
        setTimeout(() => { if (isMounted) setCurrentStepIndex(3); }, 1500);

        const report = await geminiService.generateDynamicSkillGapReport(payload);

        // Step 4: Building Path...
        if (isMounted) {
          setCurrentStepIndex(4);
          setTimeout(() => {
            if (isMounted) onComplete(report);
          }, 1000);
        }
      } catch (error) {
        console.error("Skill Gap Analysis Error:", error);
        if (isMounted) {
          setCurrentStepIndex(4);
          setTimeout(() => {
            if (isMounted) onComplete({ _error: true, message: `Analysis Failed: ${error.message || "The AI service was temporarily busy or encountered an error."}` });
          }, 1000);
        }
      }
    }

    performAnalysis();

    return () => { isMounted = false; };
  }, [targetRole, inputData, onComplete]);

  return (
    <div className="w-full max-w-lg mx-auto bg-white rounded-[24px] border border-slate-100 shadow-xl shadow-slate-200/20 p-8 lg:p-12 animate-in fade-in zoom-in-95 duration-500">
      <div className="flex flex-col items-center text-center mb-8">
        <div className="w-20 h-20 bg-[#F4F2FF] rounded-full flex items-center justify-center mb-6 relative">
          <Bot size={40} className="text-[#6C4CF1] absolute z-10" />
          <div className="absolute inset-0 border-4 border-[#6C4CF1] border-t-transparent rounded-full animate-spin opacity-30" />
          <div className="absolute inset-[-8px] border-2 border-[#6C4CF1] border-b-transparent rounded-full animate-spin-[3s_linear_infinite] opacity-10" />
        </div>
        <h1 className="text-2xl font-black text-slate-900 mb-2">Analyzing Your Skills</h1>
        <p className="text-slate-500 font-medium">OpportunityOS Copilot is generating your report...</p>
      </div>

      <div className="space-y-4 max-w-sm mx-auto">
        {STEPS.map((step, idx) => {
          const isActive = idx === currentStepIndex;
          const isDone = idx < currentStepIndex;

          return (
            <div 
              key={step} 
              className={`flex items-center gap-4 p-3 rounded-xl transition-all duration-300 ${
                isActive ? 'bg-indigo-50 border border-indigo-100 scale-105' : 
                isDone ? 'opacity-80' : 'opacity-40'
              }`}
            >
              <div className="shrink-0">
                {isDone ? (
                  <CheckCircle2 size={24} className="text-[#10B981]" />
                ) : isActive ? (
                  <Loader2 size={24} className="text-[#6C4CF1] animate-spin" />
                ) : (
                  <div className="w-6 h-6 rounded-full border-2 border-slate-300" />
                )}
              </div>
              <span className={`font-bold ${
                isActive ? 'text-[#6C4CF1]' : 
                isDone ? 'text-slate-700' : 'text-slate-500'
              }`}>
                {step}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// @ts-nocheck
import { useState, useEffect, useRef } from 'react';
import { X, Users, Tag, AlignLeft, LayoutGrid, CheckCircle, Image as ImageIcon, Shield, Globe, Lock } from 'lucide-react';
import { useTeam } from '../../contexts/TeamContext';
import toast from 'react-hot-toast';

export default function CreateTeamModal({ onClose }) {
  const { createTeam } = useTeam();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    description: '',
    category: 'Hackathon',
    maxMembers: 4,
    visibility: 'Public', // 'Public' or 'Private'
    logo: null
  });

  const [skills, setSkills] = useState([]);
  const [skillInput, setSkillInput] = useState('');

  const fileInputRef = useRef(null);

  // Prevent background scrolling
  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = 'auto';
    };
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };



  // Skill Chip Logic
  const handleSkillKeyDown = (e) => {
    if (e.key === 'Enter' || e.key === ',') {
      e.preventDefault();
      addSkill();
    }
  };

  const addSkill = () => {
    const trimmed = skillInput.trim();
    if (!trimmed) return;

    if (trimmed.length > 30) {
      toast.error('Skill name is too long (max 30 chars)');
      return;
    }

    if (skills.length >= 10) {
      toast.error('You can only add up to 10 required skills');
      return;
    }

    if (!skills.includes(trimmed)) {
      setSkills(prev => [...prev, trimmed]);
    }
    setSkillInput('');
  };

  const removeSkill = (skillToRemove) => {
    setSkills(prev => prev.filter(s => s !== skillToRemove));
  };

  // Image Upload Logic
  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) { // 2MB limit for localStorage safety
        toast.error('Image size must be less than 2MB');
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, logo: reader.result }));
      };
      reader.readAsDataURL(file);
    }
  };

  const removeLogo = () => {
    setFormData(prev => ({ ...prev, logo: null }));
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Validation
    if (!formData.name.trim()) {
      toast.error('Team Name is required');
      return;
    }
    if (formData.name.trim().length > 80) {
      toast.error('Team Name must be 80 characters or less');
      return;
    }
    if (!formData.description.trim()) {
      toast.error('Team Description is required');
      return;
    }
    if (formData.description.trim().length > 500) {
      toast.error('Team Description must be 500 characters or less');
      return;
    }
    if (parseInt(formData.maxMembers) < 2 || parseInt(formData.maxMembers) > 20) {
      toast.error('Team size must be between 2 and 20 members');
      return;
    }
    if (skills.length === 0) {
      toast.error('Please add at least one required skill');
      return;
    }
    if (skills.length > 10) {
      toast.error('Maximum 10 required skills allowed');
      return;
    }

    try {
      setIsSubmitting(true);

      const teamData = {
        name: formData.name.trim(),
        description: formData.description.trim(),
        category: formData.category,
        requiredSkills: skills,
        maxMembers: parseInt(formData.maxMembers),
        visibility: formData.visibility,
        logo: formData.logo
      };

      await createTeam(teamData);
      // Removed duplicate toast.success since TeamContext already triggers it
      onClose();
    } catch (err) {
      // Removed duplicate toast.error since TeamContext already triggers it
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6 overflow-y-auto">
      {/* Backdrop */}
      <div 
        className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200"
        onClick={onClose}
      />

      {/* Modal */}
      <div className="relative w-full max-w-2xl bg-white rounded-2xl shadow-2xl animate-in fade-in zoom-in-95 duration-200 my-8">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-5 border-b border-slate-100 bg-white rounded-t-[24px] sticky top-0 z-10">
          <div>
            <h2 className="text-[18px] font-extrabold text-slate-900">Create New Team</h2>
            <p className="text-[13px] font-medium text-slate-500 mt-0.5">Fill in the details to start recruiting members.</p>
          </div>
          <button 
            onClick={onClose}
            className="w-8 h-8 flex items-center justify-center rounded-full bg-slate-100 text-slate-500 hover:bg-slate-200 transition-colors"
          >
            <X size={16} />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="p-6">
          <div className="flex flex-col gap-6">

            {/* Logo Upload */}
            <div className="flex flex-col gap-2">
              <label className="text-[13px] font-bold text-slate-700">Team Logo (Optional)</label>
              <div className="flex items-center gap-4">
                <div 
                  className={`w-16 h-16 rounded-2xl border-2 border-dashed flex items-center justify-center overflow-hidden shrink-0 ${
                    formData.logo ? 'border-[#6C4CF1]' : 'border-slate-200 bg-slate-50'
                  }`}
                >
                  {formData.logo ? (
                    <img src={formData.logo} alt="Team Logo" className="w-full h-full object-cover" />
                  ) : (
                    <ImageIcon size={20} className="text-slate-400" />
                  )}
                </div>
                <div className="flex flex-col gap-1.5">
                  <div className="flex items-center gap-2">
                    <button
                      type="button"
                      onClick={() => fileInputRef.current?.click()}
                      className="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 text-[12px] font-bold rounded-lg transition-colors"
                    >
                      {formData.logo ? 'Change Logo' : 'Upload Logo'}
                    </button>
                    {formData.logo && (
                      <button
                        type="button"
                        onClick={removeLogo}
                        className="px-3 py-1.5 text-red-600 hover:bg-red-50 text-[12px] font-bold rounded-lg transition-colors"
                      >
                        Remove
                      </button>
                    )}
                  </div>
                  <p className="text-[11px] text-slate-500 font-medium">Recommended size: 256x256px. Max 2MB.</p>
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    onChange={handleImageUpload} 
                    accept="image/*" 
                    className="hidden" 
                  />
                </div>
              </div>
            </div>

            {/* Team Name */}
            <div className="flex flex-col gap-1.5">
              <label className="text-[13px] font-bold text-slate-700 flex items-center gap-1.5">
                <Users size={14} className="text-[#6C4CF1]" /> Team Name <span className="text-red-500">*</span>
              </label>
              <input 
                type="text" 
                name="name"
                value={formData.name}
                onChange={handleChange}
                maxLength={80}
                placeholder="e.g. AI Innovators"
                className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-[13px] font-medium focus:bg-white focus:border-[#6C4CF1] focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none"
              />
            </div>

            {/* Category & Max Members Row */}
            <div className="flex flex-col sm:flex-row gap-4 sm:gap-6">
              <div className="flex flex-col gap-1.5 flex-1">
                <label className="text-[13px] font-bold text-slate-700 flex items-center gap-1.5">
                  <LayoutGrid size={14} className="text-[#6C4CF1]" /> Category
                </label>
                <select 
                  name="category"
                  value={formData.category}
                  onChange={handleChange}
                  className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-[13px] font-medium text-slate-700 focus:bg-white focus:border-[#6C4CF1] focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none appearance-none"
                >
                  <option value="Hackathon">Hackathon</option>
                  <option value="Startup">Startup</option>
                  <option value="Project">Project</option>
                  <option value="Competition">Competition</option>
                  <option value="Open Source">Open Source</option>
                </select>
              </div>

              <div className="flex flex-col gap-1.5 w-full sm:w-[150px]">
                <label className="text-[13px] font-bold text-slate-700 flex items-center gap-1.5">
                  <Users size={14} className="text-[#6C4CF1]" /> Capacity
                </label>
                <input 
                  type="number" 
                  name="maxMembers"
                  min="2"
                  max="20"
                  value={formData.maxMembers}
                  onChange={handleChange}
                  className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-[13px] font-medium text-slate-700 focus:bg-white focus:border-[#6C4CF1] focus:ring-4 focus:ring-indigo-500/10 transition-all outline-none"
                />
