                    Add
                  </button>
                </div>

                {/* Skill Chips */}
                {skills.length > 0 && (
                  <div className="flex flex-wrap gap-2 mt-1">
                    {skills.map(skill => (
                      <div key={skill} className="flex items-center gap-1 bg-indigo-50 text-[#6C4CF1] border border-indigo-100 px-3 py-1.5 rounded-lg text-[12px] font-bold">
