import React, { useState, useEffect } from 'react';
import { Sparkles, GitBranch, Target, User, Code, BarChart3, Lock } from 'lucide-react';
import { useCareer } from '../../contexts/CareerContext';

const ROLES = [
  "Software Engineer",
  "Full Stack Developer",
  "Frontend Developer",
  "Backend Developer",
  "AI Engineer",
  "Machine Learning Engineer",
  "Data Scientist",
  "Data Analyst",
  "Cloud Engineer",
  "DevOps Engineer",
  "Cyber Security Engineer",
  "Mobile App Developer"
];

export default function GithubUpload({ onAnalyze, loading }) {
  const { careerContext } = useCareer();
  const [username, setUsername] = useState('');
  const [error, setError] = useState('');
  const [isValidating, setIsValidating] = useState(false);

  // Use context targetRole if available and it exists in ROLES list, otherwise fallback to first role
  const initialRole = careerContext?.targetRole && ROLES.includes(careerContext.targetRole)
    ? careerContext.targetRole
    : ROLES[0];

  const [targetRole, setTargetRole] = useState(initialRole);

  useEffect(() => {
    if (careerContext?.targetRole && ROLES.includes(careerContext.targetRole)) {
      setTargetRole(careerContext.targetRole);
    }
  }, [careerContext?.targetRole]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const trimmedUsername = username.trim();
    if (!trimmedUsername) {
      setError('Please enter a GitHub username.');
      return;
    }

    setIsValidating(true);
    setError('');

    try {
      const result = await onAnalyze(trimmedUsername, targetRole);

      if (result && !result.success) {
        if (result.error === 'USER_NOT_FOUND') {
          setError('GitHub user not found. Please check the username and try again.');
        } else {
          // If it fails for another reason, we can set a generic error or rely on parent's toast
          setError('');
        }
      }
    } catch (err) {
      setError('An error occurred. Please try again.');
    } finally {
      setIsValidating(false);
    }
  };

  return (
    <div className="max-w-[1000px] mx-auto px-4 py-4 lg:py-6">

      {/* Hero Section */}
      <div className="flex flex-col lg:flex-row items-center justify-between gap-6 mb-6">
        {/* Left: Text Content */}
        <div className="flex-1 space-y-3 text-center lg:text-left">
          <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-[#F4F2FF] text-[#6D5DF6] rounded-full text-[13px] font-bold tracking-wide">
            <Sparkles size={16} /> OpportunityOS GitHub Analyzer
          </div>
          <h1 className="text-4xl md:text-[40px] lg:text-[44px] font-extrabold text-[#111827] tracking-tight leading-[1.1]">
            Analyze Your GitHub
          </h1>
          <p className="text-base lg:text-lg text-slate-500 max-w-xl mx-auto lg:mx-0 leading-relaxed font-medium">
            Get AI-powered insights about your repositories, technologies, contributions, and career alignment.
          </p>
        </div>

        {/* Right: Decorative Illustration */}
        <div className="relative w-full max-w-[400px] lg:max-w-[420px] h-[220px] hidden sm:block shrink-0">
          {/* Faint Window Outline */}
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[340px] h-[180px] bg-white border border-slate-100 rounded-2xl shadow-[0_8px_30px_rgba(0,0,0,0.02)] overflow-hidden">
            <div className="h-8 border-b border-slate-50 flex items-center px-4 gap-1.5 bg-slate-50/50">
              <div className="w-2.5 h-2.5 rounded-full bg-slate-200"></div>
              <div className="w-2.5 h-2.5 rounded-full bg-slate-200"></div>
              <div className="w-2.5 h-2.5 rounded-full bg-slate-200"></div>
            </div>
            <div className="p-4 space-y-3">
              <div className="h-2 w-3/4 bg-slate-100 rounded-full"></div>
              <div className="h-2 w-1/2 bg-slate-100 rounded-full"></div>
              <div className="h-2 w-5/6 bg-slate-100 rounded-full"></div>
            </div>
          </div>

          {/* Main GitHub Bubble */}
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[120px] h-[120px] rounded-full bg-gradient-to-br from-[#6D5DF6] to-[#5542F6] flex items-center justify-center shadow-[0_0_60px_rgba(109,93,246,0.25)] z-10 border-4 border-white">
            <svg viewBox="0 0 24 24" width="60" height="60" stroke="currentColor" strokeWidth="2.5" fill="none" strokeLinecap="round" strokeLinejoin="round" className="text-white relative z-20">
              <path d="M15 22v-4a4.8 4.8 0 0 0-1-3.5c3 0 6-2 6-5.5.08-1.25-.27-2.48-1-3.5.28-1.15.28-2.35 0-3.5 0 0-1 0-3 1.5-2.64-.5-5.36-.5-8 0C6 2 5 2 5 2c-.3 1.15-.3 2.35 0 3.5A5.403 5.403 0 0 0 4 9c0 3.5 3 5.5 6 5.5-.39.49-.68 1.05-.85 1.65-.17.6-.22 1.23-.15 1.85v4"></path>
              <path d="M9 18c-4.51 2-5-2-7-2"></path>
            </svg>

            {/* Glow rings */}
            <div className="absolute inset-0 rounded-full border border-[#6D5DF6]/20 scale-[1.3]"></div>
            <div className="absolute inset-0 rounded-full border border-[#6D5DF6]/10 scale-[1.6]"></div>
          </div>

          {/* Decorative Badges */}
          <div className="absolute top-[30%] left-[5%] w-14 h-14 bg-white rounded-xl shadow-[0_8px_20px_rgba(16,185,129,0.15)] border border-emerald-50 flex items-center justify-center z-20 transform -rotate-6">
             <Code size={24} className="text-emerald-500" />
          </div>

          <div className="absolute bottom-[20%] right-[5%] w-14 h-14 bg-white rounded-xl shadow-[0_8px_20px_rgba(245,158,11,0.15)] border border-orange-50 flex items-center justify-center z-20 transform rotate-6">
             <BarChart3 size={24} className="text-orange-400" />
          </div>
        </div>
      </div>

      {/* Main Analysis Card */}
      <div className="bg-white rounded-[20px] p-5 sm:p-6 lg:px-8 shadow-[0_8px_30px_rgba(0,0,0,0.04)] border border-slate-100">

        {/* Card Header */}
        <div className="flex items-center gap-4 mb-5">
           <div className="w-10 h-10 rounded-full bg-slate-900 flex items-center justify-center shrink-0">
             <svg viewBox="0 0 24 24" width="20" height="20" stroke="currentColor" strokeWidth="2" fill="none" strokeLinecap="round" strokeLinejoin="round" className="text-white">
                <path d="M15 22v-4a4.8 4.8 0 0 0-1-3.5c3 0 6-2 6-5.5.08-1.25-.27-2.48-1-3.5.28-1.15.28-2.35 0-3.5 0 0-1 0-3 1.5-2.64-.5-5.36-.5-8 0C6 2 5 2 5 2c-.3 1.15-.3 2.35 0 3.5A5.403 5.403 0 0 0 4 9c0 3.5 3 5.5 6 5.5-.39.49-.68 1.05-.85 1.65-.17.6-.22 1.23-.15 1.85v4"></path>
                <path d="M9 18c-4.51 2-5-2-7-2"></path>
              </svg>
           </div>
           <div>
             <h2 className="text-[22px] font-extrabold text-[#111827] mb-1 tracking-tight">Connect Your GitHub Profile</h2>
             <p className="text-[15px] font-medium text-slate-500">Enter your GitHub username and select your target role to get started.</p>
           </div>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="space-y-5">

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 lg:gap-6">
            {/* Username Field */}
            <div className="space-y-1.5">
              <label className="flex items-center gap-1.5 text-[13px] font-bold text-slate-700">
                <User size={14} className="text-slate-400" /> GitHub Username
              </label>
              <input
                type="text"
                value={username}
                onChange={(e) => {
                  setUsername(e.target.value);
                  if (error) setError('');
                }}
                placeholder="e.g. torvalds"
                className={`w-full px-4 py-2.5 bg-white border rounded-xl focus:bg-slate-50 focus:ring-4 transition-all outline-none font-medium text-slate-900 placeholder:text-slate-400 ${
                  error 
                    ? 'border-red-300 focus:border-red-400 focus:ring-red-50' 
                    : 'border-slate-200 focus:border-[#6D5DF6] focus:ring-[#6D5DF6]/10'
                }`}
                required
              />
              {error && (
                <p className="text-red-500 text-[13px] font-medium mt-1.5 flex items-center gap-1.5">
                  <svg viewBox="0 0 24 24" width="14" height="14" stroke="currentColor" strokeWidth="2" fill="none" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="8" x2="12" y2="12"></line><line x1="12" y1="16" x2="12.01" y2="16"></line></svg>
                  {error}
                </p>
              )}
            </div>

            {/* Target Role Field */}
            <div className="space-y-1.5">
              <label className="flex items-center gap-1.5 text-[13px] font-bold text-slate-700">
                <Target size={14} className="text-[#6D5DF6]" /> Target Role
              </label>
              <div className="relative">
                <select
                  value={targetRole}
                  onChange={(e) => setTargetRole(e.target.value)}
                  className="w-full px-4 py-2.5 bg-white border border-slate-200 rounded-xl focus:bg-slate-50 focus:border-[#6D5DF6] focus:ring-4 focus:ring-[#6D5DF6]/10 transition-all outline-none font-medium text-slate-900 appearance-none"
                >
                  {ROLES.map(role => (
                    <option key={role} value={role}>{role}</option>
                  ))}
                </select>
                <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none">
                  <svg width="12" height="8" viewBox="0 0 12 8" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M1 1.5L6 6.5L11 1.5" stroke="#64748B" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  </svg>
                </div>
              </div>
            </div>
          </div>

          <div className="pt-1">
            <button
              type="submit"
              disabled={loading || isValidating || !username.trim()}
              className="w-full flex items-center justify-center gap-2.5 bg-gradient-to-r from-[#6D5DF6] to-[#5542F6] text-white px-8 py-3 rounded-xl text-[15px] font-bold hover:shadow-[0_8px_20px_rgba(109,93,246,0.25)] hover:-translate-y-0.5 transition-all disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none disabled:shadow-none"
            >
              {loading || isValidating ? (
                <>
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  {isValidating ? 'Checking GitHub...' : 'Analyzing Profile...'}
                </>
              ) : (
                <>
                  <GitBranch size={20} /> Analyze GitHub
                </>
              )}
            </button>
          </div>

          <div className="text-center pt-1">
            <p className="inline-flex items-center gap-1.5 text-[12px] font-medium text-slate-400">
              <Lock size={12} /> We only read public data. Your privacy is safe with us.
            </p>
          </div>
        </form>
      </div>

    </div>
  );
}

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { 
  Monitor, BrainCircuit, BarChart, ShieldCheck, Laptop, Cpu, Zap, Settings, Building, MoreHorizontal,
  Code2, Layers, BarChart2, Bot, Infinity as InfinityIcon, Shield, Cloud, User, Smartphone, Sparkles, ArrowRight
} from 'lucide-react';

const SPECIALIZATIONS = [
  { id: 'Computer Science', label: 'Computer Science', icon: Monitor, color: 'text-indigo-500' },
  { id: 'AI & ML', label: 'AI & ML', icon: BrainCircuit, color: 'text-blue-500' },
  { id: 'Data Science', label: 'Data Science', icon: BarChart, color: 'text-purple-500' },
  { id: 'Cyber Security', label: 'Cyber Security', icon: ShieldCheck, color: 'text-emerald-500' },
  { id: 'Information Technology', label: 'Information Technology', icon: Laptop, color: 'text-sky-500' },
  { id: 'ECE', label: 'ECE', icon: Cpu, color: 'text-teal-500' },
  { id: 'EEE', label: 'EEE', icon: Zap, color: 'text-violet-500' },
  { id: 'Mechanical', label: 'Mechanical', icon: Settings, color: 'text-slate-500' },
  { id: 'Civil', label: 'Civil', icon: Building, color: 'text-blue-400' },
  { id: 'Other', label: 'Other', icon: MoreHorizontal, color: 'text-slate-600' }
];

const TARGET_ROLES = [
  { id: 'Software Engineer', label: 'Software Engineer', icon: Code2, color: 'text-indigo-500' },
  { id: 'Full Stack Developer', label: 'Full Stack Developer', icon: Layers, color: 'text-emerald-500' },
  { id: 'Data Scientist', label: 'Data Scientist', icon: BarChart2, color: 'text-purple-500' },
  { id: 'AI/ML Engineer', label: 'AI/ML Engineer', icon: Bot, color: 'text-emerald-500' },
  { id: 'DevOps Engineer', label: 'DevOps Engineer', icon: InfinityIcon, color: 'text-indigo-500' },
  { id: 'Cyber Security Engineer', label: 'Cyber Security Engineer', icon: Shield, color: 'text-emerald-600' },
  { id: 'Cloud Engineer', label: 'Cloud Engineer', icon: Cloud, color: 'text-sky-500' },
  { id: 'Product Manager', label: 'Product Manager', icon: User, color: 'text-violet-500' },
  { id: 'Mobile App Developer', label: 'Mobile App Developer', icon: Smartphone, color: 'text-blue-500' },
  { id: 'Other', label: 'Other', icon: MoreHorizontal, color: 'text-slate-600' }
];

function SelectionCard({ item, selected, onClick }) {
  const Icon = item.icon;
  return (
    <button
      onClick={() => onClick(item.id)}
      className={`relative w-full p-4 rounded-2xl border transition-all duration-200 flex flex-col items-center justify-center gap-3 bg-white hover:border-[#6D4AFF] group ${
        selected 
          ? 'border-[#6D4AFF] bg-[#6D4AFF]/[0.02] shadow-[0_4px_20px_-4px_rgba(109,74,255,0.1)]' 
          : 'border-slate-200 shadow-sm'
      }`}
    >
      <div className={`p-2 rounded-xl transition-colors ${selected ? 'bg-[#6D4AFF]/10' : 'bg-slate-50 group-hover:bg-[#6D4AFF]/5'}`}>
        <Icon className={`w-6 h-6 ${selected ? 'text-[#6D4AFF]' : item.color}`} />
      </div>
      <span className={`text-[13px] font-bold ${selected ? 'text-[#6D4AFF]' : 'text-slate-700'}`}>
        {item.label}
      </span>
      {selected && (
        <div className="absolute top-3 right-3 w-5 h-5 bg-[#6D4AFF] rounded-full flex items-center justify-center text-white">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="20 6 9 17 4 12"></polyline>
          </svg>
        </div>
      )}
    </button>
  );
}

export default function EmptyState({ 
  specialization, 
  setSpecialization, 
  targetRole, 
  setTargetRole, 
  onGenerate 
}) {
  const [step, setStep] = useState(1);

  const handleContinue = () => {
    if (specialization) setStep(2);
  };

  const handleBack = () => {
    setStep(1);
    setTargetRole(''); // Optional: clear target role if going back
  };

  return (
    <div className="flex flex-col items-center w-full">
      <div className="text-center mb-10">
        <h2 className="text-3xl font-bold text-slate-900 mb-3 flex items-center justify-center gap-2">
          Let's build something amazing <span className="text-2xl">🚀</span>
        </h2>
        <p className="text-slate-500 text-sm">
          Tell us your academic background and the role you're aiming for.<br/>
          We'll generate project ideas that help you get there.
        </p>
      </div>

      <div className="w-full max-w-[1100px] bg-white border border-[#EAEAEA] rounded-[20px] p-8 md:p-10 shadow-sm">

        {step === 1 && (
          <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: 20 }}>
            {/* Section 1 */}
            <div className="mb-12">
              <div className="flex items-start gap-4 mb-6">
                <div className="w-8 h-8 rounded-full bg-[#6D4AFF] text-white flex items-center justify-center font-bold text-sm shrink-0 mt-0.5">
                  1
                </div>
                <div>
                  <h3 className="text-xl font-bold text-slate-900">What is your specialization?</h3>
                  <p className="text-sm text-slate-500 mt-1">Select your primary field of study or expertise.</p>
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-3 lg:grid-cols-5 gap-4 ml-12">
                {SPECIALIZATIONS.map(spec => (
                  <SelectionCard 
                    key={spec.id} 
                    item={spec} 
                    selected={specialization === spec.id}
                    onClick={setSpecialization}
                  />
                ))}
              </div>
            </div>

            {/* CTA Step 1 */}
            <div className="flex flex-col items-center justify-center pt-8 border-t border-slate-100">
              <button
                onClick={handleContinue}
                disabled={!specialization}
                className={`px-8 py-4 rounded-[14px] font-bold text-[15px] flex items-center gap-2 transition-all shadow-[0_4px_14px_rgba(109,74,255,0.3)] ${
                  specialization 
                    ? 'bg-gradient-to-r from-[#6D4AFF] to-[#8668FF] text-white hover:shadow-[0_6px_20px_rgba(109,74,255,0.4)] hover:-translate-y-0.5' 
                    : 'bg-slate-100 text-slate-400 shadow-none cursor-not-allowed'
                }`}
              >
                Continue
                <ArrowRight className="w-5 h-5" />
              </button>
            </div>
          </motion.div>
        )}

        {step === 2 && (
          <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }}>

            {/* Display Selected Specialization */}
            <div className="mb-8 ml-12 flex items-center justify-between bg-indigo-50/50 border border-indigo-100 rounded-xl p-4">
              <div>
                <p className="text-xs font-bold text-[#6D4AFF] uppercase tracking-wider mb-1">Selected Specialization</p>
                <p className="text-slate-800 font-semibold">{SPECIALIZATIONS.find(s => s.id === specialization)?.label || specialization}</p>
              </div>
              <button onClick={handleBack} className="text-sm font-medium text-slate-500 hover:text-[#6D4AFF] transition-colors underline">
                Change
              </button>
            </div>

            {/* Section 2 */}
            <div className="mb-12">
              <div className="flex items-start gap-4 mb-6">
                <div className="w-8 h-8 rounded-full bg-[#6D4AFF] text-white flex items-center justify-center font-bold text-sm shrink-0 mt-0.5">
                  2
                </div>
                <div>
                  <h3 className="text-xl font-bold text-slate-900">What role are you targeting?</h3>
                  <p className="text-sm text-slate-500 mt-1">Select the career role you're working towards.</p>
                </div>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-3 lg:grid-cols-5 gap-4 ml-12">
                {TARGET_ROLES.map(role => (
                  <SelectionCard 
                    key={role.id} 
                    item={role} 
                    selected={targetRole === role.id}
                    onClick={setTargetRole}
                  />
                ))}
              </div>
            </div>

            {/* CTA Section */}
            <div className="flex flex-col items-center justify-center pt-8 border-t border-slate-100">
              <button
                onClick={onGenerate}
                disabled={!targetRole}
                className={`px-8 py-4 rounded-[14px] font-bold text-[15px] flex items-center gap-2 transition-all shadow-[0_4px_14px_rgba(109,74,255,0.3)] ${
                  targetRole 
                    ? 'bg-gradient-to-r from-[#6D4AFF] to-[#8668FF] text-white hover:shadow-[0_6px_20px_rgba(109,74,255,0.4)] hover:-translate-y-0.5' 
                    : 'bg-slate-100 text-slate-400 shadow-none cursor-not-allowed'
                }`}
              >
                <Sparkles className="w-5 h-5" />
                Generate Project Ideas
              </button>
              <p className="text-slate-500 text-[13px] mt-4 font-medium">
                We'll suggest real-world, portfolio-worthy projects just for you.
              </p>
            </div>
          </motion.div>
        )}
      </div>
    </div>
  );
}

