              <BrainCircuit className="w-5 h-5 text-indigo-600" />
            </div>
            <div>
              <h4 className="text-sm font-bold text-slate-900 mb-1">Why This Project?</h4>
              <p className="text-sm text-slate-700 leading-relaxed">{project.whyThisProject}</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

