const ENABLE_AI_NOTIFICATIONS = false;

export function useCareerRoadmap() {
  const [state, dispatch] = useReducer(reducer, INITIAL);
  
  const { profile, mergeProfileData } = useProfile();
  const uidRef = useRef(null);
  const dispatch$ = useRef(dispatch);
  dispatch$.current = dispatch;

  useEffect(() => {
    const unsub = onAuthStateChanged(auth, async (firebaseUser) => {
      if (!firebaseUser) {
        uidRef.current = null;
        dispatch$.current({ type: 'NO_USER' });
        return;
      }

      const uid = firebaseUser.uid;
      uidRef.current = uid;
      dispatch$.current({ type: 'FETCH_START', uid });

      try {
        const snap = await getDoc(doc(db, 'career_roadmaps', uid));
        if (snap.exists()) {
          dispatch$.current({ type: 'FETCH_OK', data: snap.data() });
        } else {
          dispatch$.current({ type: 'NO_ROADMAP' });
        }
      } catch (err) {
        if (err.code === 'permission-denied') {
          dispatch$.current({ type: 'NO_ROADMAP' });
        } else {
          dispatch$.current({ type: 'FETCH_ERROR', error: `Could not load roadmap (${err.message})` });
        }
      }
    });

    return unsub;
  }, []);

  const generate = useCallback(async (wizardData) => {
    const uid = uidRef.current;
    if (!uid) return dispatch$.current({ type: 'GEN_ERROR', error: 'Not authenticated.' });

    dispatch$.current({ type: 'GEN_START' });

    const maxRetries = 3;
    const retryDelays = [3000, 6000, 9000];
    let attempt = 0;
    let parsed = null;
    let fallbackUsed = false;

    const apiKey = import.meta.env.VITE_GEMINI_API_KEY;
    console.log("[STEP 1] Wizard data loaded");
    const wizardWithProfile = { ...wizardData, missingSkills: profile?.missingSkills || [] };
    const promptText = buildPrompt(wizardWithProfile);
    
    const request = {
      feature: 'Career Roadmap',
      prompt: promptText,
      responseType: 'json',
      options: {
        temperature: 0.2,
        timeoutMs: 60000
      }
    };

    while (attempt <= maxRetries && !parsed) {
      try {
        console.log(`[Roadmap Gen] Attempt ${attempt + 1}`);
        console.log("[STEP 2] AIProvider request starting");
        
        const timeoutPromise = new Promise((_, reject) => 
          setTimeout(() => reject(new Error('Generation timeout')), 65000)
        );
        const response = await Promise.race([aiGenerate(request), timeoutPromise]);
        
        if (!response.success) {
          throw response.error;
        }
        
        console.log("[STEP 3] AIProvider response received");
        parsed = response.data;
        console.log("[STEP 4] Roadmap parsed");
      } catch (err) {
        console.error(`[Roadmap Gen] Attempt ${attempt + 1} failed:`, err);
        if (attempt < maxRetries) {
          const delay = retryDelays[attempt];
          console.log(`[Roadmap Gen] Retrying in ${delay}ms...`);
          await new Promise(res => setTimeout(res, delay));
        }
        attempt++;
      }
    }

    if (!parsed) {
      console.log('[Roadmap Gen] All attempts failed. Using fallback template.');
      parsed = getTemplateRoadmap(wizardData.targetCareer);
      fallbackUsed = true;
    }

    try {
      // Ensure IDs
      (parsed.phases || []).forEach((p, i) => {
        if (!p.id) p.id = `phase_${i + 1}`;
        (p.tasks || []).forEach((t, j) => {
          if (!t.id) t.id = `${p.id}_t${j + 1}`;
        });
      });

      const docData = {
        userId: uid,
        ...wizardData,
        roadmapData: parsed,
        completedTasks: [],
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        isFallback: fallbackUsed
      };

      console.log("[STEP 5] Firestore save starting");
      await setDoc(doc(db, 'career_roadmaps', uid), docData);
      console.log("[STEP 6] Firestore save successful");
      dispatch$.current({ type: 'GEN_OK', data: { ...docData, createdAt: new Date() } });
      console.log("[STEP 10] Local state updated");
      
      await mergeProfileData({ 
        targetRole: wizardData.targetCareer,
        hasRoadmap: true,
        roadmapProgress: { totalTasks: 25, completedTasks: 0 } 
      });

      if (ENABLE_AI_NOTIFICATIONS) {
        if (fallbackUsed) {
          
        } else {
          
        }
        console.log("[STEP 9] Notification created");
      }
      if (!fallbackUsed) {
        analyticsService.trackEvent('Roadmap Generated', { targetCareer: wizardData.targetCareer });
        console.log("[STEP 8] Analytics tracking successful");
      }
      console.log("[STEP 11] Navigation successful");
    } catch (saveErr) {
      console.error('[Roadmap Gen] Save Error:', saveErr);
      dispatch$.current({ type: 'GEN_ERROR', error: 'Failed to save roadmap to database.' });
    }
  }, [profile, mergeProfileData]);

  const toggleTask = useCallback(async (taskId, done) => {
    const uid = uidRef.current;
    if (!uid || !state.roadmap) return;

    const prev = state.roadmap.completedTasks || [];
    const next = done ? [...new Set([...prev, taskId])] : prev.filter(id => id !== taskId);

    const updated = { ...state.roadmap, completedTasks: next };
    dispatch$.current({ type: 'TASK_UPDATE', roadmap: updated });

    try {
      await updateDoc(doc(db, 'career_roadmaps', uid), { completedTasks: next, updatedAt: serverTimestamp() });
      
      await mergeProfileData({ 
        roadmapProgress: { totalTasks: 25, completedTasks: next.length } 
      });
      
      if (done) {
        const phase = state.roadmap.roadmapData?.phases?.find(p => p.tasks.some(t => t.id === taskId));
        if (phase) {
          const allPhaseTasks = phase.tasks.map(t => t.id);
          const wereAllCompleted = allPhaseTasks.every(id => prev.includes(id));
          const areAllCompleted = allPhaseTasks.every(id => next.includes(id));
          if (!wereAllCompleted && areAllCompleted) {
             
          }
        }
      }
    } catch (err) {
      console.error('Failed to update task:', err);
    }
  }, [state.roadmap]);

  const reset = useCallback(async () => {
    const uid = uidRef.current;
    if (uid) {
      try {
        await deleteDoc(doc(db, 'career_roadmaps', uid));
      } catch (err) {
        console.error('Failed to delete roadmap:', err);
      }
    }
    dispatch$.current({ type: 'RESET' });
  }, []);

  return { state, generate, toggleTask, reset };
}

import { useMemo } from 'react';
import { useUserProfile } from './useUserProfile';
import { useResumeInsights } from './useResumeInsights';
import { useCareerReadiness } from './useCareerReadiness';

export function useDashboardInsights() {
  const { profile, isLoading: isProfileLoading } = useUserProfile();
  const { hasInsights: hasResume, atsScore, missingSkills: resumeMissingSkills } = useResumeInsights();
  const { score: readinessScore, breakdown } = useCareerReadiness();

  const insights = useMemo(() => {
    // 1. Next Best Action
    let nextBestAction = null;
    let nextBestActionCta = null;
    let nextBestActionLink = null;
    let nextBestActionIcon = null;

    if (!profile?.name || !profile?.college) {
      nextBestAction = "Complete your profile to unlock better matches.";
      nextBestActionCta = "Complete Profile";
      nextBestActionLink = "/profile";
      nextBestActionIcon = "User";
    } else if (!hasResume) {
      nextBestAction = "Upload a resume to unlock AI analysis.";
      nextBestActionCta = "Upload Resume";
      nextBestActionLink = "/resume-review";
      nextBestActionIcon = "FileText";
    } else if (!profile?.skills || (profile.skills || []).length < 3) {
      nextBestAction = "Add more skills to improve your recommendation accuracy.";
      nextBestActionCta = "Add Skills";
      nextBestActionLink = "/profile";
      nextBestActionIcon = "Code";
    } else if (typeof atsScore === 'number' && atsScore < 60) {
      nextBestAction = "Your ATS score is low. Update your resume to improve visibility.";
      nextBestActionCta = "Improve Resume";
      nextBestActionLink = "/resume-review";
      nextBestActionIcon = "AlertTriangle";
    } else {
      nextBestAction = "Keep up the momentum! Explore new career paths.";
      nextBestActionCta = "Explore Career Paths";
      nextBestActionLink = "/career-explorer";
      nextBestActionIcon = "Zap";
    }

    // 2. Profile Completion
    const requiredFields = ['name', 'email', 'bio', 'college', 'branch', 'location'];
    let filled = 0;
    const missingProfileItems = [];
    requiredFields.forEach(field => {
      if (profile?.[field]) {
        filled++;
      } else {
        missingProfileItems.push(field);
      }
    });
    if (!hasResume) missingProfileItems.push('resume');
    if (!profile?.skills || (profile.skills || []).length === 0) missingProfileItems.push('skills');

    // Calculate total fields to evaluate completion
    const totalFields = requiredFields.length + 2;
    let totalFilled = filled;
    if (hasResume) totalFilled++;
    if (profile?.skills?.length > 0) totalFilled++;
    const profileCompletionPct = Math.round((totalFilled / totalFields) * 100);

    // 5. Skill Gap Analysis
    // Aggregate required skills from top 5 recommendations
    const requiredByOps = {};
    const userSkillsSet = new Set((profile?.skills || []).map(s => s.toLowerCase()));
    if (profile?.resumeSkills) {
      profile.resumeSkills.forEach(s => userSkillsSet.add(s.toLowerCase()));
    }

    const missingSkillsGap = Object.keys(requiredByOps)
      .filter(skill => !userSkillsSet.has(skill))
      .sort((a, b) => requiredByOps[b] - requiredByOps[a])
      .slice(0, 5); // Top 5 missing skills



    return {
      nextBestAction: {
        text: nextBestAction,
        cta: nextBestActionCta,
        link: nextBestActionLink,
        icon: nextBestActionIcon
      },
      profileCompletion: {
        score: profileCompletionPct,
        missing: missingProfileItems
      },

      skillGap: {
        current: Array.from(userSkillsSet).slice(0, 5),
        missing: missingSkillsGap
      },

      careerReadiness: {
        score: readinessScore,
        breakdown
      }
    };
  }, [profile, hasResume, atsScore, readinessScore, breakdown]);

  return {
    ...insights,
    isLoading: isProfileLoading
  };
}

import { useState, useEffect, useCallback } from 'react';
import { useResume } from '../contexts/ResumeContext';
import { useResumeHistory } from './useResumeHistory';
import { useTeam } from '../contexts/TeamContext';
import { useAuth } from '../contexts/AuthContext';
import { useProfile } from '../contexts/ProfileContext';
import { geminiService } from '../services/geminiService';
import { db } from '../config/firebase';
import { collection, addDoc, serverTimestamp } from 'firebase/firestore';


const CACHE_EXPIRY_MS = 24 * 60 * 60 * 1000;
const ENABLE_AI_NOTIFICATIONS = false;

export function useGeminiSkillGap(opportunity) {
  const { resumeData } = useResume();
  const { getBestVersion } = useResumeHistory();

  const { teams } = useTeam();
  const { user } = useAuth();
  const { profile, mergeProfileData } = useProfile();

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);
  const [gapData, setGapData] = useState(null);

  const bestVersion = getBestVersion();

  const generateGapAnalysis = useCallback(async (forceRefresh = false) => {
    if (!opportunity || !opportunity.id) return;
    if (!user) return;

    const cacheKey = `gemini_skill_gap_${opportunity.id}`;

    if (!forceRefresh) {
      const cachedString = localStorage.getItem(cacheKey);
      if (cachedString) {
        try {
          const cached = JSON.parse(cachedString);
          if (Date.now() - cached.timestamp < CACHE_EXPIRY_MS) {
            setGapData(cached.data);
            return;
          }
        } catch (e) {
          console.warn("Invalid cache data", e);
        }
      }
    }

    setIsLoading(true);
    setError(null);

    const contextData = {
      opportunity: {
        title: opportunity.title,
        company: opportunity.company,
        requiredSkills: opportunity.requiredSkills,
        description: opportunity.fullDescription,
        type: opportunity.type,
      },
      user: {
        skills: profile?.extractedSkills || user.skills || [],
        interests: user.interests || [],
        goals: user.goals || [],
      },
      resume: {
        skills: resumeData?.skills || [],
        experience: resumeData?.experience || [],
        projects: resumeData?.projects || [],
        certifications: resumeData?.certifications || [],
      },
      atsScore: bestVersion?.results?.overallScore || 0,
      applicationsCount: 0,
      teamsCount: teams?.length || 0,
    };

    try {
      if (!import.meta.env.VITE_GEMINI_API_KEY) {
        throw new Error('VITE_GEMINI_API_KEY is not configured.');
      }

      const results = await geminiService.analyzeSkillGap(contextData);

      if (results) {
        setGapData(results);
        localStorage.setItem(cacheKey, JSON.stringify({ timestamp: Date.now(), data: results }));

        // Save generated analysis to Firebase
        await addDoc(collection(db, 'skill_gap_analysis'), {
          uid: user.id,
          generatedAt: serverTimestamp(),
          currentSkills: results.currentSkills || [],
          missingSkills: results.missingSkills || [],
          prioritySkills: results.prioritySkills || [],
          recommendations: results.recommendations || [],
          reasoning: results.reasoning || ""
        }).catch(err => console.error("Firebase save failed", err));

        if (results.missingSkills?.length > 0) {
          await mergeProfileData({ missingSkills: results.missingSkills });
        }

        if (!cachedString && ENABLE_AI_NOTIFICATIONS) {
                  }
      }
    } catch (err) {
      console.error("Skill Gap Analysis Error:", err);
      setError("Unable to generate analysis. Please try again.");
    } finally {
      setIsLoading(false);
    }
  }, [opportunity, resumeData, bestVersion, teams, user]);

  // Removed automatic execution on load. Call generateGapAnalysis manually.

  return {
    isLoading,
    error,
    gapData,
    generateGapAnalysis
  };
}

