import { useState, useEffect, useCallback } from 'react';
import { db } from '../config/firebase';
import { doc, onSnapshot, setDoc } from 'firebase/firestore';
import { useAuth } from '../contexts/AuthContext';
import { geminiService } from '../services/geminiService';
import { toast } from 'react-hot-toast';

export function useMatchResume() {
  const { user } = useAuth();

  const [matchResume, setMatchResume] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isUploading, setIsUploading] = useState(false);

  useEffect(() => {
    if (!user?.id) {
      setMatchResume(null);
      setIsLoading(false);
      return;
    }

    setIsLoading(true);
    const docRef = doc(db, 'users', user.id, 'match_resume', 'current');

    const unsubscribe = onSnapshot(docRef, (docSnap) => {
      if (docSnap.exists()) {
        setMatchResume(docSnap.data());
      } else {
        setMatchResume(null);
      }
      setIsLoading(false);
    }, (error) => {
      console.error('[Match Resume] Real-time Fetch Error:', error);
      setIsLoading(false);
    });

    return () => unsubscribe();
  }, [user?.id]);

  const fetchMatchResume = useCallback(async () => {
    // No-op for backwards compatibility, handled by onSnapshot now
  }, []);

  const uploadNewResume = async (file) => {
    if (!user) {
      toast.error('You must be logged in to upload a resume.');
      return null;
    }

    console.log('[Resume Pipeline] Upload started');
    setIsUploading(true);
    try {
      // Extract base64
      const fileBase64 = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result.split(',')[1]);
        reader.onerror = error => reject(error);
      });
      console.log('[Resume Pipeline] Text extraction completed');

      // Pass to Gemini for text & skill extraction
      console.log('[Resume Pipeline] Gemini request started');
      const analysisResult = await geminiService.analyzeResume({
        mimeType: file.type,
        base64: fileBase64
      });
      console.log('[Resume Pipeline] Gemini response received');

      const extractedSkills = analysisResult?.extractedSkills || [];
      console.log('[Resume Pipeline] Skills parsed', extractedSkills.length);

      const resumeText = analysisResult?.summary || "Resume parsed successfully.";

      // Save to Firestore
      const payload = {
        user_id: user.id,
        resume_file_name: file.name,
        resume_text: resumeText,
        extracted_skills: extractedSkills,
        upload_date: new Date().toISOString(),
        last_updated: new Date().toISOString()
      };

      const docRef = doc(db, 'users', user.id, 'match_resume', 'current');
      await setDoc(docRef, payload);

      console.log('[Resume Pipeline] Profile updated');
      console.log('[Resume Pipeline] Upload completed');
      toast.success('Resume successfully processed and saved.');
      return payload;
    } catch (err) {
      console.error('[Match Resume] Upload Error:', err);
      toast.error('Error: ' + (err.message || 'Failed to parse and save resume'));
      return null;
    } finally {
      console.log('[Resume Pipeline] Loading state cleared');
      setIsUploading(false);
    }
  };

  const syncBuilderResume = async (builderData) => {
    if (!user) return null;

    try {
      // Format builder data into raw text
      const generateText = (data) => {
        let text = `Name: ${data.personalInfo?.fullName || ''}\n`;
        text += `Email: ${data.personalInfo?.email || ''}\n\n`;

        if (data.education?.length) {
          text += `Education:\n`;
          data.education.forEach(e => {
            text += `- ${e.degree} at ${e.school} (${e.startDate} - ${e.endDate})\n`;
          });
          text += `\n`;
        }

        if (data.experience?.length) {
          text += `Experience:\n`;
          data.experience.forEach(e => {
            text += `- ${e.title} at ${e.company} (${e.startDate} - ${e.endDate})\n  ${e.description}\n`;
          });
          text += `\n`;
        }

        if (data.projects?.length) {
          text += `Projects:\n`;
          data.projects.forEach(p => {
            text += `- ${p.title}\n  ${p.description}\n`;
          });
          text += `\n`;
        }

        if (data.skills?.length) {
          text += `Skills:\n${data.skills.join(', ')}\n`;
        }

        return text;
      };

      const payload = {
        user_id: user.id,
        resume_file_name: 'Resume Builder Profile',
        resume_text: generateText(builderData),
        extracted_skills: builderData.skills || [],
        upload_date: matchResume?.upload_date || new Date().toISOString(),
        last_updated: new Date().toISOString()
      };

      const docRef = doc(db, 'users', user.id, 'match_resume', 'current');
      await setDoc(docRef, payload);

      return payload;
    } catch (err) {
      console.error('[Match Resume] Sync Builder Error:', err);
      return null;
    }
  };

  return {
    matchResume,
    isLoading,
    isUploading,
    uploadNewResume,
    syncBuilderResume,
    fetchMatchResume
  };
}

import { useMemo } from 'react';


export function calculateMatchScore(opportunity, userProfile) {
  if (!opportunity) return null;

  let score = 0;
  const reasons = [];

  // Parse User Profile Data
  const userCountryRaw = userProfile?.country || userProfile?.profile?.country || '';
  const userCountry = String(userCountryRaw).toLowerCase();

  const userBranchRaw = userProfile?.branch || '';
  const userBranch = String(userBranchRaw).toLowerCase();

  const onboardingSkills = (userProfile?.skills || []).map(s => s.toLowerCase());
  const resumeSkills = (userProfile?.resumeSkills || []).map(s => s.toLowerCase());
  const userSkillsRaw = [...new Set([...(userProfile?.skills || []), ...(userProfile?.resumeSkills || [])])];
  const userSkills = [...new Set([...onboardingSkills, ...resumeSkills])];

  const userInterestsRaw = userProfile?.interests || [];
  const userInterests = userInterestsRaw.map(i => i.toLowerCase());

  const userGoalsRaw = userProfile?.careerGoals || userProfile?.goals || [];
  const userGoals = userGoalsRaw.map(g => g.toLowerCase());

  // Prepare Opportunity Data for matching
  const oppTitle = String(opportunity.title || '').toLowerCase();
  const oppDesc = String(opportunity.description || '').toLowerCase();
  const oppSkills = (opportunity.skills || []).map(s => String(s).toLowerCase());
  const oppType = String(opportunity.type || '').toLowerCase();
  const oppCountryRaw = opportunity.country || opportunity.location || '';
  const oppCountry = (Array.isArray(oppCountryRaw) ? oppCountryRaw.join(' ') : String(oppCountryRaw)).toLowerCase();

  const searchContent = `${oppTitle} ${oppDesc} ${oppSkills.join(' ')} ${oppType}`;

  // 1. Country Match (+30)
  if (userCountry && oppCountry.includes(userCountry)) {
    score += 30;
    const displayCountry = userCountryRaw.charAt(0).toUpperCase() + userCountryRaw.slice(1);
    reasons.push(`Available in ${displayCountry}`);
  }

  // 2. Branch Match (+25)
  if (userBranch && searchContent.includes(userBranch)) {
    score += 25;
    reasons.push(`Matches your ${userBranchRaw} background`);
  }

  // 3. Skills Match (+35)
  let matchedSkillsCount = 0;
  let matchedSkillNames = [];
  if (userSkills.length > 0) {
    userSkills.forEach((skill, index) => {
      if (searchContent.includes(skill)) {
        matchedSkillsCount++;
        matchedSkillNames.push(userSkillsRaw[index]);
      }
    });

    const skillsRatio = matchedSkillsCount / Math.max(1, userSkills.length);
    const skillsPoints = Math.round(skillsRatio * 35);
    score += skillsPoints;

    if (matchedSkillNames.length > 0) {
      // Pick the first matched skill for the reason
      reasons.push(`Matches your ${matchedSkillNames[0]} skills`);
    }
  }

  // 4. Career Goal / Interest Match (+10)
  let goalOrInterestMatched = false;
  let matchedItemName = '';

  if (userGoals.length > 0) {
    for (let i = 0; i < userGoals.length; i++) {
      const goal = userGoals[i];
      const goalKw = goal.endsWith('s') ? goal.slice(0, -1) : goal;
      if (searchContent.includes(goalKw)) {
        goalOrInterestMatched = true;
        matchedItemName = userGoalsRaw[i];
        reasons.push(`Matches your ${matchedItemName} goals`);
        break;
      }
    }
  }

  if (!goalOrInterestMatched && userInterests.length > 0) {
    for (let i = 0; i < userInterests.length; i++) {
      const interest = userInterests[i];
      if (searchContent.includes(interest)) {
        goalOrInterestMatched = true;
        matchedItemName = userInterestsRaw[i];
        reasons.push(`Matches your ${matchedItemName} interests`);
        break;
      }
    }
  }

  if (goalOrInterestMatched) {
    score += 10;
  }

  // Cap score at 100
  score = Math.min(100, Math.max(0, score));

  // Remove duplicate reasons
  const uniqueReasons = [...new Set(reasons)].slice(0, 3); // Max 3 reasons on UI

  return {
    score,
    reasons: uniqueReasons,
    matchedSkillsCount,
    totalSkillsCount: userSkills.length,
    matchedGoal: goalOrInterestMatched
  };
}

import { useProfile } from '../contexts/ProfileContext';

export function useMatchScore(opportunity) {
  const { profile } = useProfile();

  const matchData = useMemo(() => {
    return calculateMatchScore(opportunity, profile);
  }, [opportunity, profile]);

  return matchData;
}

import { useState, useCallback, useMemo } from 'react';
import { geminiService } from '../services/geminiService';
import { useProfile } from '../contexts/ProfileContext';
import { useResume } from '../contexts/ResumeContext';
import { useCareerRoadmap } from './useCareerRoadmap';
import { useMatchResume } from './useMatchResume';

export function useOpportunityMatch() {
  const { resumeData } = useResume();
  const { state: roadmapState } = useCareerRoadmap();
  const { matchResume, uploadNewResume } = useMatchResume();
  const { mergeProfileData } = useProfile();

  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [matchResult, setMatchResult] = useState(null);
  const [error, setError] = useState(null);

  const profileContext = useMemo(() => {
    // A real resume exists if it's stored in match_resumes
    const actuallyHasResume = !!matchResume;

    // Check for other context data
    const hasRoadmap = roadmapState?.roadmap != null;

    // Collect skills primarily from matchResume and resumeData
    const extractedSkills = matchResume?.extracted_skills || [];
    const builderSkills = resumeData?.skills || [];

    const allSkills = new Set([
      ...extractedSkills,
      ...builderSkills
    ]);

    // Phase 4: Match Confidence
    let confidence = 'Low';
    const totalSkillsExtracted = allSkills.size;

    if (actuallyHasResume) {
      if (totalSkillsExtracted > 10 || (totalSkillsExtracted > 5 && hasRoadmap)) {
        confidence = 'High';
      } else if (totalSkillsExtracted > 0) {
        confidence = 'Medium';
      }
    }

    const sources = [];
    if (actuallyHasResume) sources.push('Uploaded Resume');
    else if (allSkills.size > 0) sources.push('Manual Profile');

    if (hasRoadmap) sources.push('Career Roadmap');

    console.log('[Opportunity Match Profile Detection]', {
      resumeFound: actuallyHasResume,
      skillsCount: allSkills.size,
      hasRoadmap,
      confidenceCalculation: confidence
    });

    return {
      skills: Array.from(allSkills),
      sourcesUsed: sources,
      confidence,
      actuallyHasResume
    };
  }, [resumeData, roadmapState, matchResume]);

  const analyzeMatch = useCallback(async (opportunityText, uploadedResumeFile = null) => {
    setIsAnalyzing(true);
    setError(null);

    try {
      const contextToUse = { ...profileContext };

      // If user provided a new file right now, parse it and extract skills via useMatchResume
      if (uploadedResumeFile) {
        const newMatchResume = await uploadNewResume(uploadedResumeFile);
        if (newMatchResume?.extracted_skills) {
          contextToUse.skills = [...new Set([...contextToUse.skills, ...newMatchResume.extracted_skills])];
          if (!contextToUse.sourcesUsed.includes('Uploaded Resume')) {
            contextToUse.sourcesUsed.push('Uploaded Resume');
            contextToUse.confidence = 'High';
            contextToUse.actuallyHasResume = true;
          }
        }
      }

      if (contextToUse.skills.length === 0) {
        throw new Error('No resume profile data found. Please upload a resume first.');
      }

      // Pass the full resumeData along with contextToUse so the deterministic engine has access to projects and experience
      const fullResumePayload = {
        ...resumeData,
        skills: contextToUse.skills // Ensure we use the merged skills (including any newly extracted ones)
      };

      const result = await geminiService.analyzeOpportunityMatch(contextToUse, opportunityText, fullResumePayload);

      if (result?.missingSkills?.length > 0) {
        mergeProfileData({ missingSkills: result.missingSkills });
      }

      setMatchResult({
        ...result,
        sourcesUsed: contextToUse.sourcesUsed,
        confidence: contextToUse.confidence
      });

    } catch (err) {
      console.error('[Opportunity Match Error]', err);
      setError(err.message || 'Failed to analyze match. Using approximation.');

      try {
        const { calculateMatchScore } = await import('../utils/matchScoringEngine');
        const fallbackReqs = { requiredSkills: opportunityText.split(/\s+/).slice(0, 50) };
        const fallbackResult = calculateMatchScore(resumeData || contextToUse, fallbackReqs);

        setMatchResult({
          currentMatchScore: fallbackResult.currentMatchScore || 50,
          potentialMatchScore: fallbackResult.potentialMatchScore || 70,
          strengths: fallbackResult.strengths || [],
          missingSkills: [],
          recommendations: ['AI analysis temporarily unavailable. Match score is an approximation.'],
          sourcesUsed: contextToUse.sourcesUsed,
          confidence: 'Low'
        });
      } catch (fallbackErr) {
        setMatchResult(null);
      }
    } finally {
      setIsAnalyzing(false);
    }
  }, [profileContext, uploadNewResume, resumeData]);

  return {
    analyzeMatch,
    isAnalyzing,
    matchResult,
    error,
    profileContext
  };
}

