import { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { db } from '../config/firebase';
import { doc, onSnapshot } from 'firebase/firestore';

export function useResumeInsights() {
  const { user } = useAuth();
  const [isLoading, setIsLoading] = useState(true);
  const [atsScore, setAtsScore] = useState(null);
  const [topStrength, setTopStrength] = useState(null);
  const [topWeakness, setTopWeakness] = useState(null);
  const [missingSkills, setMissingSkills] = useState([]);
  const [nextAction, setNextAction] = useState(null);
  const [storedResumeName, setStoredResumeName] = useState(null);
  const [hasInsights, setHasInsights] = useState(false);

  useEffect(() => {
    if (!user?.id) {
      setHasInsights(false);
      setIsLoading(false);
      return;
    }

    setIsLoading(true);
    const docRef = doc(db, 'users', user.id);

    const unsubscribe = onSnapshot(docRef, (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        const saved = {
          analysis: data.resumeAnalysis || null,
          resume: data.resume || null
        };
        applyAnalysisData(saved);
      } else {
        setHasInsights(false);
      }
      setIsLoading(false);
    }, (err) => {
      console.error('useResumeInsights Real-time Fetch Error:', err);
      setHasInsights(false);
      setIsLoading(false);
    });

    return () => unsubscribe();
  }, [user?.id]);

  const applyAnalysisData = useCallback((saved) => {
    if (saved?.analysis) {
      const a = saved.analysis;
      const parsedScore = parseInt(a.atsScore, 10);
      const score = !isNaN(parsedScore) ? parsedScore : null;
      setAtsScore(score);
      setTopStrength(a.strengths?.[0] || null);
      setTopWeakness(a.weaknesses?.[0] || null);
      setMissingSkills(a.missingKeywords?.slice(0, 3) || []);

      const highPriority = a.improvements?.find(i => i.priority === 'HIGH');
      if (highPriority) {
        setNextAction(highPriority.description);
      } else if (a.recommendedSkills?.length > 0) {
        setNextAction(`Build a project using ${a.recommendedSkills[0]} to strengthen your profile.`);
      } else {
        setNextAction('Add quantifiable metrics to your experience section to improve your ATS score.');
      }

      setHasInsights(true);
    } else {
      setHasInsights(false);
    }

    if (saved?.resume?.fileName) {
      setStoredResumeName(saved.resume.fileName);
    }
  }, []);

  const loadInsights = useCallback(() => {
    // No-op for backwards compatibility, handled by onSnapshot
  }, []);

  return {
    isLoading,
    hasInsights,
    atsScore,
    topStrength,
    topWeakness,
    missingSkills,
    nextAction,
    storedResumeName,
    reload: loadInsights
  };
}

import { useMemo } from 'react';
import { useUserProfile } from './useUserProfile';
import { useTeam } from '../contexts/TeamContext';

export function useTeamMatch() {
  const { profile } = useUserProfile();
  const { teams, getDiscoverTeams } = useTeam();

  const userSkills = useMemo(() => {
    const skills = new Set((profile?.skills || []).map(s => s.toLowerCase()));
    if (profile?.resumeSkills) {
      profile.resumeSkills.forEach(s => skills.add(s.toLowerCase()));
    }
    return skills;
  }, [profile]);

  const userInterests = useMemo(() => {
    return new Set((profile?.interests || []).map(i => i.toLowerCase()));
  }, [profile]);

  const userGoals = useMemo(() => {
    return new Set((profile?.careerGoals || []).map(g => g.toLowerCase()));
  }, [profile]);

  const calculateMatch = (team) => {
    let score = 0;
    const reasons = [];

    // 1. Skills Match (up to 50%)
    if (team.requiredSkills && team.requiredSkills.length > 0) {
      const matchedSkills = team.requiredSkills.filter(s => userSkills.has(s.toLowerCase()));
      const skillScore = (matchedSkills.length / team.requiredSkills.length) * 50;
      score += skillScore;

      matchedSkills.slice(0, 3).forEach(s => {
        reasons.push(`✓ ${s} (Skill)`);
      });
    } else {
      // If no required skills, give default points
      score += 30; 
    }

    // 2. Interests/Goals Match against Project Idea / Description (up to 50%)
    const textToSearch = `${team.projectIdea || ''} ${team.description || ''}`.toLowerCase();

    let interestMatches = 0;
    userInterests.forEach(interest => {
      if (textToSearch.includes(interest)) {
        interestMatches++;
        if (reasons.length < 5 && !reasons.includes(`✓ ${interest} (Interest)`)) {
          reasons.push(`✓ ${interest} (Interest)`);
        }
      }
    });

    userGoals.forEach(goal => {
      if (textToSearch.includes(goal)) {
        interestMatches++;
        if (reasons.length < 5 && !reasons.includes(`✓ ${goal} (Goal)`)) {
          reasons.push(`✓ ${goal} (Goal)`);
        }
      }
    });

    const contextScore = Math.min((interestMatches * 15), 50);
    score += contextScore;

    // Minimum score of 15 just so things don't look completely zero if there's no perfect match but they are exploring
    return {
      score: Math.max(15, Math.round(score)),
      reasons: reasons.slice(0, 3) // Return top 3 reasons
    };
  };

  const getRecommendedTeams = () => {
    const discoverable = getDiscoverTeams();

    const evaluated = discoverable.map(team => {
      const matchData = calculateMatch(team);
      return {
        ...team,
        matchData
      };
    });

    // Sort by highest match score
    return evaluated.sort((a, b) => b.matchData.score - a.matchData.score);
  };

  return {
    calculateMatch,
    getRecommendedTeams
  };
}

