import { useState, useEffect } from 'react';
import { db } from '../../config/firebase';
import { collection, query, where, getDocs, doc, deleteDoc, setDoc, serverTimestamp, updateDoc } from 'firebase/firestore';
import { toast } from 'react-hot-toast';
import { ShieldAlert, CheckCircle2, XCircle, Search, Building2, Briefcase, MapPin, Clock, BarChart3, Users, FileText, Map, Target, MessageSquare } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';
import ConfirmationModal from '../../components/common/ConfirmationModal';

export default function AdminDashboardPage() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [pendingOpps, setPendingOpps] = useState([]);
  const [metrics, setMetrics] = useState({
    totalUsers: 0,
    activeUsers: 0,
    resumeAnalyses: 0,
    roadmapsGenerated: 0,
    matchAnalyses: 0,
    careerCoach: 0
  });
  const [isLoading, setIsLoading] = useState(true);

  // Modal state
  const [actionOpportunity, setActionOpportunity] = useState(null); // { opp, action: 'approve' | 'reject' }
  const [isConfirming, setIsConfirming] = useState(false);

  useEffect(() => {
    // Basic admin check - in a real app this would be a strict middleware
    if (user?.user_type !== 'admin') {
      toast.error('Unauthorized access');
      navigate('/dashboard');
      return;
    }

    fetchPendingOpportunities();
    fetchMetrics();
  }, [user, navigate]);

  const fetchMetrics = async () => {
    try {
      const snapshot = await getDocs(collection(db, 'telemetry_events'));
      const events = snapshot.docs.map(doc => doc.data());

      const uniqueUsers = new Set(events.filter(e => e.userId && e.userId !== 'anonymous').map(e => e.userId)).size;

      setMetrics({
        totalUsers: uniqueUsers, // Approximated by active users in telemetry
        activeUsers: uniqueUsers,
        resumeAnalyses: events.filter(e => e.eventName === 'Resume Analysis Completed').length,
        roadmapsGenerated: events.filter(e => e.eventName === 'Roadmap Generated').length,
        matchAnalyses: events.filter(e => e.eventName === 'Match Analysis Completed').length,
        careerCoach: events.filter(e => e.eventName === 'Message Sent').length,
      });
    } catch (error) {
      console.error('Error fetching metrics:', error);
    }
  };

  const fetchPendingOpportunities = async () => {
    setIsLoading(true);
    try {
      const q = query(
        collection(db, 'pending_opportunities'),
        where('status', '==', 'pending')
      );
      const snapshot = await getDocs(q);
      const opps = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      // Sort by newest
      opps.sort((a, b) => (b.createdAt?.toMillis() || 0) - (a.createdAt?.toMillis() || 0));
      setPendingOpps(opps);
    } catch (error) {
      console.error('Error fetching pending opportunities:', error);
      toast.error('Failed to load pending opportunities');
    } finally {
      setIsLoading(false);
    }
  };

  const triggerAction = (opp, action) => {
    setActionOpportunity({ opp, action });
  };

  const executeAction = async () => {
    if (!actionOpportunity) return;
    const { opp, action } = actionOpportunity;
    setIsConfirming(true);

    try {
      if (action === 'approve') {
        const newOppId = `community_${Date.now()}_${opp.id.substring(0, 5)}`;
        const newOppData = {
          title: opp.title,
          organization: opp.organization,
          type: opp.type,
          description: opp.description || '',
          country: opp.country || '',
          location: opp.country || '',
          deadline: opp.deadline || '',
          applyUrl: opp.applyUrl,
          logoUrl: opp.logoUrl || null,
          skills: opp.skills || [],
          source: 'Community',
          status: 'active',
          createdAt: serverTimestamp(),
          approvedBy: user.uid
        };

        await setDoc(doc(db, 'opportunities', newOppId), newOppData);
        await updateDoc(doc(db, 'pending_opportunities', opp.id), {
          status: 'approved',
          approvedAt: serverTimestamp(),
          approvedBy: user.uid
        });

        toast.success('Opportunity approved and published!');
        setPendingOpps(prev => prev.filter(o => o.id !== opp.id));
      } else if (action === 'reject') {
        await updateDoc(doc(db, 'pending_opportunities', opp.id), {
          status: 'rejected',
          rejectedAt: serverTimestamp(),
          rejectedBy: user.uid
        });

        toast.success('Opportunity rejected');
        setPendingOpps(prev => prev.filter(o => o.id !== opp.id));
      }
    } catch (error) {
      console.error(`Error ${action}ing opportunity:`, error);
      toast.error(`Failed to ${action} opportunity`);
    } finally {
      setIsConfirming(false);
      setActionOpportunity(null);
    }
  };

  if (isLoading) {
    return (
      <div className="p-8 max-w-6xl mx-auto flex items-center justify-center min-h-[400px]">
        <div className="w-8 h-8 border-4 border-[#6C4CF1] border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="p-8 max-w-6xl mx-auto">
      <div className="flex items-center gap-3 mb-8">
        <div className="w-12 h-12 bg-red-100 text-red-600 rounded-xl flex items-center justify-center">
          <ShieldAlert size={24} />
        </div>
        <div>
          <h1 className="text-2xl font-extrabold text-slate-900">Admin Dashboard</h1>
          <p className="text-slate-500">Review and moderate community submissions.</p>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4 mb-8">
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col">
          <div className="flex items-center gap-2 text-slate-500 mb-2">
            <Users size={16} />
            <span className="text-xs font-bold uppercase tracking-wider">Total Users</span>
          </div>
          <span className="text-2xl font-black text-slate-900">{metrics.totalUsers}</span>
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col">
          <div className="flex items-center gap-2 text-slate-500 mb-2">
            <BarChart3 size={16} />
            <span className="text-xs font-bold uppercase tracking-wider">Active</span>
          </div>
          <span className="text-2xl font-black text-indigo-600">{metrics.activeUsers}</span>
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col">
          <div className="flex items-center gap-2 text-slate-500 mb-2">
            <FileText size={16} />
            <span className="text-xs font-bold uppercase tracking-wider">Resumes</span>
          </div>
          <span className="text-2xl font-black text-slate-900">{metrics.resumeAnalyses}</span>
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col">
          <div className="flex items-center gap-2 text-slate-500 mb-2">
            <Map size={16} />
            <span className="text-xs font-bold uppercase tracking-wider">Roadmaps</span>
          </div>
          <span className="text-2xl font-black text-slate-900">{metrics.roadmapsGenerated}</span>
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col">
          <div className="flex items-center gap-2 text-slate-500 mb-2">
            <Target size={16} />
            <span className="text-xs font-bold uppercase tracking-wider">Matches</span>
          </div>
          <span className="text-2xl font-black text-slate-900">{metrics.matchAnalyses}</span>
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm flex flex-col">
          <div className="flex items-center gap-2 text-slate-500 mb-2">
            <MessageSquare size={16} />
            <span className="text-xs font-bold uppercase tracking-wider">Coach MSGs</span>
          </div>
          <span className="text-2xl font-black text-slate-900">{metrics.careerCoach}</span>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
        <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50">
          <h2 className="text-lg font-bold text-slate-900 flex items-center gap-2">
            Pending Opportunities
            <span className="px-2.5 py-0.5 bg-[#6D5DF6]/10 text-[#6D5DF6] rounded-full text-xs">
              {pendingOpps.length}
            </span>
          </h2>
        </div>

        {pendingOpps.length === 0 ? (
          <div className="p-12 text-center flex flex-col items-center justify-center">
            <CheckCircle2 size={48} className="text-emerald-400 mb-4" />
            <h3 className="text-xl font-bold text-slate-900 mb-2">All caught up!</h3>
            <p className="text-slate-500">There are no pending opportunities to review right now.</p>
          </div>
        ) : (
          <div className="divide-y divide-slate-100">
            {pendingOpps.map((opp) => (
              <div key={opp.id} className="p-6 hover:bg-slate-50 transition-colors">
                <div className="flex flex-col lg:flex-row gap-6">
                  {/* Left Column: Details */}
                  <div className="flex-1 space-y-4">
                    <div className="flex items-start justify-between">
                      <div>
                        <h3 className="text-lg font-extrabold text-slate-900 mb-1">{opp.title}</h3>
                        <div className="flex flex-wrap items-center gap-4 text-sm font-semibold text-slate-600">
                          <span className="flex items-center gap-1">
                            <Building2 size={14} className="text-slate-400" />
                            {opp.organization}
                          </span>
                          <span className="flex items-center gap-1">
                            <Briefcase size={14} className="text-slate-400" />
                            {opp.type}
                          </span>
                          {opp.country && (
                            <span className="flex items-center gap-1">
                              <MapPin size={14} className="text-slate-400" />
                              {opp.country}
                            </span>
                          )}
                          <span className="flex items-center gap-1">
                            <Clock size={14} className="text-slate-400" />
                            Submitted: {opp.createdAt?.toDate().toLocaleDateString() || 'Recently'}
                          </span>
                        </div>
                      </div>
                      {opp.logoUrl && (
                        <img src={opp.logoUrl} alt="Logo" className="w-12 h-12 rounded-lg object-contain border border-slate-100 bg-white" />
                      )}
                    </div>

                    <div className="text-sm text-slate-600 bg-slate-100/50 p-4 rounded-xl">
                      {opp.description || <span className="italic text-slate-400">No description provided</span>}
                    </div>

                    {opp.skills?.length > 0 && (
                      <div className="flex flex-wrap gap-2">
                        {opp.skills.map((skill, i) => (
                          <span key={i} className="px-2.5 py-1 bg-[#F4F2FF] text-[#6C4CF1] text-xs font-bold rounded-lg">
                            {skill}
                          </span>
                        ))}
                      </div>
                    )}

                    <div className="text-sm">
                      <span className="font-bold text-slate-700">Apply URL: </span>
                      <a href={opp.applyUrl} target="_blank" rel="noopener noreferrer" className="text-blue-600 hover:underline break-all">
                        {opp.applyUrl}
                      </a>
                    </div>
                  </div>

                  {/* Right Column: Actions */}
                  <div className="lg:w-[200px] shrink-0 flex flex-row lg:flex-col gap-3 justify-start">
                    <button
                      onClick={() => triggerAction(opp, 'approve')}
                      className="flex-1 lg:w-full px-4 py-2.5 bg-emerald-500 hover:bg-emerald-600 text-white font-bold rounded-xl flex items-center justify-center gap-2 transition-colors"
                    >
                      <CheckCircle2 size={18} />
                      Approve
                    </button>
                    <button
                      onClick={() => triggerAction(opp, 'reject')}
                      className="flex-1 lg:w-full px-4 py-2.5 bg-rose-50 text-rose-600 hover:bg-rose-100 font-bold rounded-xl flex items-center justify-center gap-2 transition-colors"
                    >
                      <XCircle size={18} />
                      Reject
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <ConfirmationModal
        isOpen={!!actionOpportunity}
        onClose={() => !isConfirming && setActionOpportunity(null)}
        onConfirm={executeAction}
        title={actionOpportunity?.action === 'approve' ? 'Approve Opportunity' : 'Reject Opportunity'}
        message={
          <>
            Are you sure you want to {actionOpportunity?.action} {' '}
            <span className="font-bold text-slate-900">{actionOpportunity?.opp?.title}</span>?
            {actionOpportunity?.action === 'reject' && '\n\nThis action cannot be undone.'}
          </>
        }
        confirmText={actionOpportunity?.action === 'approve' ? 'Approve' : 'Reject'}
        isDestructive={actionOpportunity?.action === 'reject'}
        isLoading={isConfirming}
      />
    </div>
  );
}

import { 
  Target,
  Trophy,
  BrainCircuit,
  FileText,
  CheckCircle2,
  ChevronRight,
  Code2,
  Briefcase,
  Clock,
  FileCheck,
  GitBranch,
  Sparkles,
  Lightbulb,
  Rocket,
  Calendar,
  User,
  TrendingUp
} from 'lucide-react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { useCareerReadiness } from '../../hooks/useCareerReadiness';
import { useResumeInsights } from '../../hooks/useResumeInsights';
import { useCareer } from '../../contexts/CareerContext';
import { useActivity } from '../../contexts/ActivityContext';
import { useUserProfile } from '../../hooks/useUserProfile';

// Helper for relative timestamps
function timeAgo(dateString) {
  if (!dateString) return 'Just now';
  const date = new Date(dateString);
  const now = new Date();
  const seconds = Math.floor((now - date) / 1000);

  if (seconds < 60) return 'Just now';
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) return `${minutes} minute${minutes > 1 ? 's' : ''} ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours} hour${hours > 1 ? 's' : ''} ago`;
  const days = Math.floor(hours / 24);
  if (days < 30) return `${days} day${days > 1 ? 's' : ''} ago`;
  const months = Math.floor(days / 30);
  if (months < 12) return `${months} month${months > 1 ? 's' : ''} ago`;
  return `${Math.floor(months / 12)} year${Math.floor(months / 12) > 1 ? 's' : ''} ago`;
}

// Helper for activity icons
const getActivityIcon = (category) => {
  const map = {
    'resume': { icon: FileCheck, color: "text-emerald-600", bg: "bg-emerald-50" },
    'github': { icon: GitBranch, color: "text-blue-600", bg: "bg-blue-50" },
    'skills': { icon: Sparkles, color: "text-purple-600", bg: "bg-purple-50" },
    'projects': { icon: Briefcase, color: "text-orange-600", bg: "bg-orange-50" },
    'profile': { icon: Target, color: "text-indigo-600", bg: "bg-indigo-50" }
  };
  return map[category?.toLowerCase()] || { icon: Clock, color: "text-slate-600", bg: "bg-slate-50" };
};

export default function AnalyticsPage() {
  const readinessData = useCareerReadiness();
  const { atsScore, hasInsights } = useResumeInsights();
  const { careerContext } = useCareer();
  const { activities } = useActivity();
  const { profile } = useUserProfile();
  const navigate = useNavigate();

  // Determine Profile Setup Progress (5 Core Milestones)
  const hasBasicProfile = !!(profile?.bio || profile?.college || profile?.name);
  const hasSkills = !!(profile?.skills?.length > 0);
  const hasTargetRole = !!(careerContext?.targetRole);
  const hasResume = !!hasInsights;
  const hasGithub = !!(careerContext?.githubScore > 0);

  const steps = [
    { id: 'profile', completed: hasBasicProfile, title: 'Complete your Profile', desc: 'Add your education, experience and career interests.', path: '/dashboard/settings', icon: User, priority: 'High Priority', color: 'text-indigo-600', bg: 'bg-indigo-50', priorityBg: 'bg-rose-50 text-rose-600' },
    { id: 'skills', completed: hasSkills, title: 'Add Your Skills', desc: 'Add relevant skills to match your career goals.', path: '/dashboard/skill-gap', icon: Code2, priority: 'High Priority', color: 'text-emerald-600', bg: 'bg-emerald-50', priorityBg: 'bg-rose-50 text-rose-600' },
    { id: 'resume', completed: hasResume, title: 'Upload Your Resume', desc: 'Upload your resume to get AI-powered insights.', path: '/dashboard/resume', icon: Briefcase, priority: 'Medium Priority', color: 'text-amber-600', bg: 'bg-amber-50', priorityBg: 'bg-amber-50 text-amber-600' },
    { id: 'github', completed: hasGithub, title: 'Connect GitHub', desc: 'Connect GitHub to analyze your activity.', path: '/dashboard/github', icon: GitBranch, priority: 'Medium Priority', color: 'text-blue-600', bg: 'bg-blue-50', priorityBg: 'bg-amber-50 text-amber-600' },
    { id: 'interests', completed: hasTargetRole, title: 'Set Career Interests', desc: 'Define your target role for better recommendations.', path: '/dashboard/settings', icon: Target, priority: 'Low Priority', color: 'text-purple-600', bg: 'bg-purple-50', priorityBg: 'bg-slate-100 text-slate-600' }
  ];

  const completedStepsCount = steps.filter(s => s.completed).length;
  const progressPercentage = (completedStepsCount / 5) * 100;

  const incompleteSteps = steps.filter(s => !s.completed);
  const nextStep = incompleteSteps[0] || { title: "Analyze Your Resume", desc: "Get AI-powered feedback on your resume.", path: "/dashboard/resume-review", icon: FileText, color: "text-emerald-600", bg: "bg-emerald-50" };

  const overviewCards = [
    {
      id: 1,
      title: 'Career Readiness',
      value: completedStepsCount < 3 ? 'Getting Started' : `${readinessData?.score || 0}%`,
      subtext: completedStepsCount < 3 ? 'Complete your profile to see your score' : (readinessData?.status || 'Good Progress'),
      subtextColor: completedStepsCount < 3 ? 'text-slate-500' : 'text-indigo-600',
      valueClass: completedStepsCount < 3 ? 'text-[24px]' : 'text-[40px]',
      icon: Target,
      iconColor: 'text-indigo-500',
      iconBg: 'bg-indigo-50'
    },
    {
      id: 2,
      title: 'Resume Score',
      value: !hasResume ? 'Not Analyzed' : `${atsScore || 0}%`,
      subtext: !hasResume ? 'Upload your resume to get started' : (atsScore > 75 ? 'Good' : 'Needs Improvement'),
      subtextColor: !hasResume ? 'text-slate-500' : (atsScore > 75 ? 'text-emerald-500' : 'text-amber-500'),
      valueClass: !hasResume ? 'text-[24px]' : 'text-[40px]',
      icon: FileText,
      iconColor: 'text-emerald-500',
      iconBg: 'bg-emerald-50'
    },
    {
      id: 3,
      title: 'GitHub Alignment',
      value: !hasGithub ? 'Not Connected' : `${careerContext?.alignmentScore || 0}%`,
      subtext: !hasGithub ? 'Connect GitHub to analyze your activity' : 'Moderate',
      subtextColor: !hasGithub ? 'text-slate-500' : 'text-amber-500',
      valueClass: !hasGithub ? 'text-[24px]' : 'text-[40px]',
      icon: GitBranch, 
      iconColor: 'text-orange-500',
      iconBg: 'bg-orange-50'
    },
    {
      id: 4,
      title: 'Skill Coverage',
      value: !hasSkills ? 'Building Profile' : `${Math.max(0, 100 - ((careerContext?.missingSkills?.length || 5) * 10))}%`,
      subtext: !hasSkills ? 'Add skills to see your coverage' : (careerContext?.missingSkills?.length > 0 ? 'Needs Improvement' : 'Excellent'),
      subtextColor: !hasSkills ? 'text-slate-500' : (careerContext?.missingSkills?.length > 0 ? 'text-rose-500' : 'text-emerald-500'),
      valueClass: !hasSkills ? 'text-[24px]' : 'text-[40px]',
      icon: Trophy,
      iconColor: 'text-blue-500',
      iconBg: 'bg-blue-50'
    }
  ];

  // Dynamic Prioritization Engine (Max 3 items)
  const improvementCards = incompleteSteps.slice(0, 3);

  // If user completed everything, give them advanced tasks
  if (improvementCards.length < 3) {
    if (improvementCards.length < 3) improvementCards.push({ title: "Build Projects", desc: "Get AI recommendations for side projects.", priority: "Medium Priority", icon: Code2, color: "text-purple-600", bg: "bg-purple-50", priorityBg: "bg-amber-50 text-amber-600", path: "/project-recommendations" });
    if (improvementCards.length < 3) improvementCards.push({ title: "Build Projects", desc: "Add real-world projects to showcase your skills.", priority: "Low Priority", icon: Briefcase, color: "text-orange-600", bg: "bg-orange-50", priorityBg: "bg-slate-100 text-slate-600", path: "/dashboard/projects" });
    if (improvementCards.length < 3) improvementCards.push({ title: "Expand Network", desc: "Connect with peers and mentors in your field.", priority: "Low Priority", icon: Target, color: "text-blue-600", bg: "bg-blue-50", priorityBg: "bg-slate-100 text-slate-600", path: "/dashboard/network" });
  }

  const recentActivities = activities?.slice(0, 5) || [];

  return (
    <div className="max-w-6xl mx-auto flex flex-col h-full relative space-y-8 pb-12 p-4 lg:p-8">
      {/* Page Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-2">
        <div>
          <h1 className="text-3xl font-extrabold text-slate-900 mb-2">Career Intelligence</h1>
          <p className="text-slate-500 font-medium">Your personalized career insights will grow as you build your profile.</p>
        </div>
        <button className="flex items-center gap-2 px-5 py-2.5 bg-white text-indigo-600 font-bold rounded-xl hover:bg-slate-50 transition-colors border border-indigo-100 shadow-[0_2px_10px_rgba(0,0,0,0.02)]">
          <FileText size={18} />
          View Reports
        </button>
      </div>

      {/* Section 1: Overview Cards */}
      <section>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {overviewCards.map((card, index) => {
            const Icon = card.icon;
            return (
              <motion.div 
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.4, delay: index * 0.1 }}
                key={card.id} 
                className="bg-white p-6 md:p-8 rounded-[32px] border border-slate-100 shadow-[0_2px_10px_rgba(0,0,0,0.02)] hover:shadow-md transition-shadow flex flex-col h-[260px] justify-between"
              >
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shrink-0 ${card.iconBg} mb-6`}>
                  <Icon size={24} strokeWidth={2.5} className={card.iconColor} />
                </div>
                <div className="flex-1 flex flex-col justify-end">
                  <h4 className="text-[15px] font-bold text-slate-900 mb-3">{card.title}</h4>
                  <div className="flex items-end justify-between mb-4">
                    <span className={`${card.valueClass} font-extrabold text-slate-700 leading-none tracking-tight`}>
                      {card.value}
                    </span>
                  </div>
                  <span className={`text-[14px] font-medium leading-relaxed ${card.subtextColor}`}>{card.subtext}</span>
                </div>
              </motion.div>
            );
          })}
        </div>
      </section>

      {/* Section 2: Career Insights Card */}
      <section>
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4, delay: 0.2 }}
          className="bg-white rounded-[32px] border border-slate-100 p-8 shadow-[0_2px_10px_rgba(0,0,0,0.02)]"
        >
          <div className="flex items-center gap-3 mb-8">
            <TrendingUp size={22} className="text-indigo-600" />
