  const activeConversation = conversations.find(c => c.id === activeConvId);

  const filteredConversations = conversations.filter(c => 
    c.participant.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const totalPages = Math.ceil(filteredConversations.length / limit) || 1;
  const paginatedConversations = filteredConversations.slice((currentPage - 1) * limit, currentPage * limit);

  const handlePageChange = (newPage) => {
    if (newPage >= 1 && newPage <= totalPages) {
      setCurrentPage(newPage);
    }
  };

  const scrollToBottom = () => {
    setTimeout(() => {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, 100);
  };

  useEffect(() => {
    if (activeConvId) {
      markConversationAsRead(activeConvId);
      scrollToBottom();
    }
  }, [activeConvId, conversations, markConversationAsRead]);

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (!messageInput.trim() || !activeConvId) return;
    sendMessage(activeConvId, messageInput.trim());
    setMessageInput('');
  };

  // Get status info for active conversation participant
  const activeStatus = activeConversation
    ? getUserStatus(activeConversation.participant.name)
    : null;

  return (
    <div className="flex h-full w-full overflow-hidden bg-[#F8FAFC]">
      {/* LEFT SIDEBAR - CONVERSATION LIST */}
      <div className={`w-full md:w-[350px] lg:w-[400px] flex flex-col bg-white border-r border-slate-200 shrink-0 h-full ${activeConvId ? 'hidden md:flex' : 'flex'}`}>

        {/* Sidebar Header */}
        <div className="p-5 border-b border-slate-100 shrink-0">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-xl font-bold text-slate-900 tracking-tight">Messages</h1>
              <p className="text-[13px] text-slate-500 mt-0.5">Connect and collaborate with teammates.</p>
            </div>
          </div>

          {hasLocalMigration && (
            <div className="mb-4 bg-indigo-50 border border-indigo-100 rounded-lg p-3">
              <h3 className="text-[13px] font-bold text-slate-900">Local Messages Found</h3>
              <p className="text-[12px] text-slate-600 font-medium mb-2">You have legacy local messages. Migrate to cloud to access everywhere.</p>
              <button 
                onClick={migrateLocalMessages}
                className="w-full bg-[#6C4CF1] hover:bg-indigo-600 text-white py-1.5 rounded-md text-[12px] font-bold transition-colors flex justify-center items-center gap-1.5"
              >
                <Cloud size={14} />
                Migrate to Cloud
              </button>
            </div>
          )}

          <div className="relative">
            <Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              placeholder="Search conversations..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              aria-label="Search conversations"
              className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium placeholder-slate-400 focus:bg-white focus:border-[#6C4CF1] focus:ring-4 focus:ring-[#6C4CF1]/10 transition-all outline-none"
            />
          </div>
        </div>

        {/* Conversations List */}
        <div className="flex-1 overflow-y-auto flex flex-col">
          <div className="flex-1">
            {paginatedConversations.length > 0 ? (
              paginatedConversations.map((conv) => {
                const { status } = getUserStatus(conv.participant.name);
                return (
                  <button
                    key={conv.id}
                    onClick={() => setActiveConvId(conv.id)}
                    className={`w-full text-left p-4 flex items-start gap-4 transition-colors border-b border-slate-50 relative ${activeConvId === conv.id ? 'bg-[#F4F2FF]' : 'hover:bg-slate-50'}`}
                  >
                    {activeConvId === conv.id && (
                      <div className="absolute left-0 top-0 bottom-0 w-1 bg-[#6C4CF1]" />
                    )}

                    {/* Avatar with status dot */}
                    <div className="relative shrink-0">
                      <img src={conv.participant.avatar} alt={conv.participant.name} className="w-12 h-12 rounded-full border border-slate-200 object-cover bg-white" />
                      {/* Status dot bottom-right of avatar */}
                      <span className="absolute bottom-0 right-0 ring-2 ring-white rounded-full">
                        <StatusDot status={status} size="md" />
                      </span>
                      {conv.unreadCount > 0 && (
                        <div className="absolute -top-0.5 -right-0.5 w-3.5 h-3.5 bg-red-500 border-2 border-white rounded-full z-10" />
                      )}
                    </div>

                    <div className="flex-1 min-w-0 pr-2">
                      <div className="flex items-center justify-between mb-1">
                        <h3 className={`text-sm truncate pr-2 ${conv.unreadCount > 0 ? 'font-bold text-slate-900' : 'font-semibold text-slate-800'}`}>
                          {conv.participant.name}
                        </h3>
                        <span className={`text-[11px] shrink-0 ${conv.unreadCount > 0 ? 'font-bold text-[#6C4CF1]' : 'font-medium text-slate-400'}`}>
                          {formatTime(conv.lastMessageTime)}
                        </span>
                      </div>
                      <p className={`text-[13px] truncate ${conv.unreadCount > 0 ? 'font-semibold text-slate-800' : 'text-slate-500'}`}>
                        {conv.lastMessage}
                      </p>
                    </div>

                    {conv.unreadCount > 0 && (
                      <div className="absolute right-4 top-1/2 -translate-y-1/2 bg-[#6C4CF1] text-white text-[10px] font-bold h-5 min-w-[20px] px-1.5 flex items-center justify-center rounded-full">
                        {conv.unreadCount}
                      </div>
                    )}
                  </button>
                );
              })
            ) : (
              <div className="p-4">
                <EmptyState
                  icon={Search}
                  title="No results"
                  description={`No conversations matching "${searchQuery}".`}
                  actionText="Clear search"
                  onAction={() => setSearchQuery('')}
                  variant="compact"
                />
              </div>
            )}
          </div>

          <div className="p-2 border-t border-slate-100 bg-slate-50 shrink-0">
            <PaginationControls 
              currentPage={currentPage}
              totalPages={totalPages}
              onPageChange={handlePageChange}
            />
          </div>
        </div>
      </div>

      {/* RIGHT PANEL - CHAT WINDOW */}
      <div className={`flex-1 flex flex-col bg-white h-full relative ${!activeConvId ? 'hidden md:flex' : 'flex'}`}>
        {activeConversation ? (
          <>
            {/* Chat Header */}
            <div className="h-[72px] px-6 border-b border-slate-100 flex items-center justify-between bg-white shrink-0">
              <div className="flex items-center gap-4">
                <button 
                  onClick={() => setActiveConvId(null)}
                  aria-label="Back to conversations"
                  className="md:hidden p-2 -ml-2 text-slate-400 hover:bg-slate-50 rounded-lg focus-visible:ring-2 focus-visible:ring-[#6C4CF1] focus-visible:outline-none"
                >
                  <ArrowLeft size={20} />
                </button>
                <div className="relative shrink-0">
                  <img src={activeConversation.participant.avatar} alt="Avatar" className="w-10 h-10 rounded-full border border-slate-200 object-cover bg-slate-50" />
                  <span className="absolute -bottom-0.5 -right-0.5 ring-2 ring-white rounded-full">
                    <StatusDot status={activeStatus?.status} size="md" />
                  </span>
                </div>
                <div>
                  <h2 className="text-[15px] font-bold text-slate-900 leading-tight">{activeConversation.participant.name}</h2>
                  {activeStatus?.status === 'online' && (
                    <p className="text-[12px] font-semibold text-emerald-500 flex items-center gap-1.5 mt-0.5">
                      Online
                    </p>
                  )}
                  {activeStatus?.status === 'away' && (
                    <p className="text-[12px] font-semibold text-amber-500 mt-0.5">Away</p>
                  )}
                  {activeStatus?.status === 'offline' && activeStatus?.lastSeen && (
                    <p className="text-[12px] font-medium text-slate-400 mt-0.5">
                      Last seen {formatLastSeen(activeStatus.lastSeen)}
                    </p>
                  )}
                </div>
              </div>

              <div className="flex items-center gap-2 text-slate-400">
                <button aria-label="Start voice call" className="p-2 hover:bg-slate-50 hover:text-slate-600 rounded-lg transition-colors hidden sm:block focus-visible:ring-2 focus-visible:ring-[#6C4CF1] focus-visible:outline-none">
                  <Phone size={18} />
                </button>
                <button aria-label="Start video call" className="p-2 hover:bg-slate-50 hover:text-slate-600 rounded-lg transition-colors hidden sm:block focus-visible:ring-2 focus-visible:ring-[#6C4CF1] focus-visible:outline-none">
                  <Video size={18} />
                </button>
                <button aria-label="More options" className="p-2 hover:bg-slate-50 hover:text-slate-600 rounded-lg transition-colors focus-visible:ring-2 focus-visible:ring-[#6C4CF1] focus-visible:outline-none">
                  <MoreVertical size={18} />
                </button>
              </div>
            </div>

            {/* Chat Messages */}
            <div className="flex-1 overflow-y-auto p-6 bg-[#F8FAFC]">
              <div className="max-w-3xl mx-auto flex flex-col justify-end min-h-full">
                {activeConversation.messages.map((msg) => {
                  const isMe = msg.sender === 'me';
                  return (
                    <div key={msg.id} className={`flex w-full mb-4 ${isMe ? 'justify-end' : 'justify-start'}`}>
                      <div className={`max-w-[75%] sm:max-w-[65%] flex flex-col ${isMe ? 'items-end' : 'items-start'}`}>
                        <div 
                          className={`px-4 py-2.5 rounded-2xl shadow-sm text-[14.5px] leading-relaxed ${
                            isMe 
                              ? 'bg-[#6C4CF1] text-white rounded-br-sm' 
                              : 'bg-white border border-slate-100 text-slate-800 rounded-bl-sm'
                          }`}
                        >
                          {msg.text}
                        </div>
                        <span className="text-[11px] text-slate-400 font-medium mt-1.5 px-1">
                          {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        </span>
                      </div>
                    </div>
                  );
                })}
                <div ref={messagesEndRef} />
              </div>
            </div>

            {/* Chat Input */}
            <div className="p-5 border-t border-slate-100 bg-white shrink-0">
              <form onSubmit={handleSendMessage} className="max-w-3xl mx-auto relative flex items-center">
                <button type="button" aria-label="Add emoji" className="absolute left-3 p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-50 rounded-lg transition-colors focus-visible:ring-2 focus-visible:ring-[#6C4CF1] focus-visible:outline-none">
                  <Smile size={20} />
                </button>
                <input
                  type="text"
                  placeholder="Type a message..."
                  value={messageInput}
                  onChange={(e) => setMessageInput(e.target.value)}
                  aria-label="Type a message"
                  className="w-full pl-12 pr-14 py-3.5 bg-[#F8FAFC] border border-transparent rounded-xl text-[14px] font-medium placeholder-slate-400 focus:bg-white focus:border-[#6C4CF1] focus:ring-4 focus:ring-[#6C4CF1]/10 transition-all outline-none"
                />
                <button 
                  type="submit"
                  disabled={!messageInput.trim()}
                  className="absolute right-2.5 w-9 h-9 flex items-center justify-center bg-[#6C4CF1] text-white rounded-lg hover:bg-[#6C4CF1] disabled:opacity-50 disabled:hover:bg-[#6C4CF1] transition-colors"
                >
                  <Send size={16} className="ml-0.5" />
                </button>
              </form>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-8 text-center">
            <div className="w-20 h-20 rounded-full bg-[#F4F2FF] flex items-center justify-center mb-4">
              <MessageSquare size={36} strokeWidth={1.5} className="text-[#6C4CF1]" />
            </div>
            <h3 className="text-[18px] font-extrabold text-slate-800 mb-1">Select a conversation</h3>
            <p className="text-[14px] text-slate-400 max-w-xs">Choose from the list on the left to start chatting with your connections.</p>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { 
  Search, Filter, 
  ChevronDown, ChevronUp, 
  RefreshCcw, ChevronLeft, ChevronRight, CheckCircle2, SearchX
} from 'lucide-react';
import EmptyState from '../../components/ui/EmptyState';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-hot-toast';
import { useApplications } from '../../contexts/ApplicationContext';
import { useSavedOpportunities } from '../../contexts/SavedOpportunitiesContext';
import { useLiveOpportunities } from '../../hooks/useLiveOpportunities';
import OpportunityCard from '../../components/opportunities/OpportunityCard';
import RecommendedForYouSection from '../../components/opportunities/RecommendedForYouSection';
import Skeleton from '../../components/ui/Skeleton';
import SubmitOpportunityModal from '../../components/opportunities/SubmitOpportunityModal';
import { PlusCircle } from 'lucide-react';

export default function OpportunitiesPage() {
  const navigate = useNavigate();
  const { applications, addApplication } = useApplications();
  const [searchQuery, setSearchQuery] = useState('');
  const { opportunities: liveOpportunities, isLoading } = useLiveOpportunities();

  const [activeTab, setActiveTab] = useState('All');
  const tabs = ['All', 'Jobs', 'Internships', 'Hackathons', 'Competitions', 'Scholarships'];

  // Filter states
  const [selectedTypes, setSelectedTypes] = useState([]);
  const [selectedLocations, setSelectedLocations] = useState([]);
  const [selectedDurations, setSelectedDurations] = useState([]);
  const [selectedCategories, setSelectedCategories] = useState([]);
  const [isMobileFiltersOpen, setIsMobileFiltersOpen] = useState(false);
  const [isSubmitModalOpen, setIsSubmitModalOpen] = useState(false);

  // Accordion open states
  const [openFilterSections, setOpenFilterSections] = useState({
    type: true,
    location: true,
    duration: true,
    category: true
  });

  // Save Logic
  const { toggleSavedOpportunity, isSaved } = useSavedOpportunities();

  const handleApply = (e, opp) => {
    e.stopPropagation();
    const targetUrl = opp.url || opp.applyLink;
    if (targetUrl && targetUrl !== '#') {
      window.open(targetUrl, '_blank');
    } else {
      toast.error('Application link not available.');
    }
  };

  const filterSections = [
    {
      id: 'type',
      title: 'Opportunity Type',
      state: selectedTypes,
      setState: setSelectedTypes,
      options: ['Job', 'Internship', 'Hackathon', 'Competition', 'Scholarship']
    },
    {
      id: 'location',
      title: 'Location',
      state: selectedLocations,
      setState: setSelectedLocations,
      options: ['Remote', 'Hybrid', 'Onsite']
    },
    {
      id: 'duration',
      title: 'Duration',
      state: selectedDurations,
      setState: setSelectedDurations,
      options: ['1 Month', '3 Months', '6 Months']
    },
    {
      id: 'category',
      title: 'Category',
      state: selectedCategories,
      setState: setSelectedCategories,
      options: ['Engineering', 'Design', 'Management', 'Product']
    }
  ];

  const handleToggle = (option, currentState, setState) => {
    setState(prev => 
      prev.includes(option) ? prev.filter(t => t !== option) : [...prev, option]
    );
  };

  const toggleFilterSection = (id) => {
    setOpenFilterSections(prev => ({ ...prev, [id]: !prev[id] }));
  };

  const clearAllFilters = () => {
    setSelectedTypes([]);
    setSelectedLocations([]);
    setSelectedDurations([]);
    setSelectedCategories([]);
  };

  // Filter Logic
  const filteredOpportunities = useMemo(() => {
    return liveOpportunities.filter(opp => {
      const query = searchQuery ? searchQuery.toLowerCase() : '';
      const matchesSearch = !query || 
        (opp.title && opp.title.toLowerCase().includes(query)) || 
        (opp.company && opp.company.toLowerCase().includes(query)) || 
        (opp.tags && Array.isArray(opp.tags) && opp.tags.some(tag => tag?.label?.toLowerCase().includes(query)));

      const mappedTabType = activeTab.endsWith('s') ? activeTab.slice(0, -1) : activeTab;
      const matchesTab = activeTab === 'All' || opp.type === mappedTabType;

      const matchesType = selectedTypes.length === 0 || selectedTypes.includes(opp.type);

      const isRemote = opp.location ? opp.location.toLowerCase().includes('remote') : false;
      let matchesLocation = true;
      if (selectedLocations.length > 0) {
        if (selectedLocations.includes('Remote') && isRemote) matchesLocation = true;
        else if (selectedLocations.includes('Onsite') && !isRemote) matchesLocation = true;
        else matchesLocation = false;
      }

      return matchesSearch && matchesTab && matchesType && matchesLocation;
    });
  }, [liveOpportunities, searchQuery, activeTab, selectedTypes, selectedLocations]);

  return (
    <div className="max-w-[1600px] mx-auto flex flex-col h-full relative p-4 lg:p-6">
      {/* Recommended For You Section */}
      <RecommendedForYouSection limit={4} layout="grid" />

      {/* Page Header */}
      <div className="mb-6">
        <h1 className="page-header">Opportunities</h1>
        <p className="page-subheader mt-0">Discover internships, hackathons, scholarships and competitions tailored for you.</p>
      </div>

      {/* Tabs */}
      <div className="flex overflow-x-auto gap-2 mb-6 pb-2 hide-scrollbar">
        {tabs.map(tab => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-5 py-2.5 rounded-full text-[14px] font-bold whitespace-nowrap transition-colors ${
              activeTab === tab
                ? 'bg-[#6C4CF1] text-white shadow-md'
                : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      {/* Header Actions */}
      <div className="flex flex-col sm:flex-row gap-4 mb-8">
        <div className="relative flex-1 max-w-[500px]">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Search by title, company or keyword..." 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            aria-label="Search opportunities"
            className="w-full pl-11 pr-4 py-3 bg-white border border-slate-200 rounded-xl text-[14px] shadow-sm placeholder:text-slate-400 focus:outline-none focus:border-[#6C4CF1] focus:ring-4 focus:ring-[#6C4CF1]/10 transition-all"
          />
        </div>
        <div className="flex gap-3 shrink-0">
          <button 
            onClick={() => setIsSubmitModalOpen(true)}
            className="px-4 py-3 bg-[#F4F2FF] text-[#6C4CF1] font-bold rounded-xl text-[14px] hover:bg-indigo-100 transition-colors flex items-center gap-2"
          >
            <PlusCircle size={18} />
            Submit Opportunity
          </button>
          <button 
            onClick={() => setIsMobileFiltersOpen(!isMobileFiltersOpen)}
            aria-expanded={isMobileFiltersOpen}
            className="btn-secondary flex items-center gap-2 text-[14px] focus-visible:ring-2 focus-visible:ring-[#6C4CF1] focus-visible:outline-none"
          >
            <Filter size={16} />
            Filter
          </button>
        </div>
        <div className="flex-1" />
        <div className="relative group shrink-0">
          <button className="btn-secondary flex items-center gap-2 text-[14px] w-full sm:w-auto justify-between sm:justify-start">
            Sort by: <span className="text-slate-900">Newest</span>
            <ChevronDown size={16} className="text-slate-400 group-hover:text-slate-600 ml-1" />
          </button>
        </div>
      </div>

      <div className="flex flex-col lg:flex-row gap-6 flex-1">
        {/* Left Sidebar Filters */}
        <div className={`
          lg:w-[260px] shrink-0
          ${isMobileFiltersOpen ? 'block' : 'hidden lg:block'}
        `}>
          <div className="card-standard p-6">
            <h2 className="section-header mb-6">Filters</h2>

            <div className="space-y-6">
              {filterSections.map((section) => (
                <div key={section.id} className="border-b border-slate-100 pb-6 last:border-0 last:pb-0">
                  <button 
                    onClick={() => toggleFilterSection(section.id)}
                    aria-expanded={openFilterSections[section.id]}
                    className="flex items-center justify-between w-full text-left mb-4 group focus-visible:ring-2 focus-visible:ring-[#6C4CF1] focus-visible:outline-none rounded-lg p-1 -ml-1"
                  >
                    <h3 className="text-[14px] font-bold text-slate-900">{section.title}</h3>
                    {openFilterSections[section.id] ? (
                      <ChevronUp size={16} className="text-slate-400 group-hover:text-slate-600" />
                    ) : (
                      <ChevronDown size={16} className="text-slate-400 group-hover:text-slate-600" />
                    )}
                  </button>

                  {openFilterSections[section.id] && (
                    <div className="space-y-3.5">
                      {section.options.map((option, optIdx) => (
                        <label key={optIdx} className="flex items-center gap-3 cursor-pointer group">
                          <div className={`
                            relative flex items-center justify-center w-[18px] h-[18px] rounded-[4px] border transition-colors
                            ${section.state.includes(option) ? 'bg-[#6C4CF1] border-[#6C4CF1]' : 'bg-white border-slate-300 group-hover:border-[#6C4CF1]'}
                          `}>
                            <input 
                              type="checkbox" 
                              className="peer opacity-0 absolute inset-0 cursor-pointer"
                              onChange={() => handleToggle(option, section.state, section.setState)}
                              checked={section.state.includes(option)}
                            />
                            {section.state.includes(option) && (
                              <CheckCircle2 size={12} className="text-white" strokeWidth={3} />
                            )}
                          </div>
                          <span className="text-[14px] text-slate-600 font-medium group-hover:text-slate-900 transition-colors">{option}</span>
                        </label>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>

            <button 
              onClick={clearAllFilters}
              className="mt-8 w-full py-3 flex items-center justify-center gap-2 border border-[#6C4CF1] text-[#6C4CF1] rounded-xl text-[14px] font-bold hover:bg-indigo-50 transition-colors"
            >
              <RefreshCcw size={14} />
              Clear All Filters
            </button>
          </div>
        </div>

        {/* Right Content Area (Grid) */}
        <div className="flex-1 flex flex-col">
          {isLoading ? (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-6">
              {[1,2,3,4,5,6,7,8].map(i => (
                <div key={i} className="animate-pulse bg-white rounded-2xl p-6 border border-slate-100 h-[280px]">
                  <div className="flex gap-4 mb-4">
                    <div className="w-12 h-12 bg-slate-200 rounded-xl"></div>
                    <div className="flex-1 space-y-2 py-1">
                      <div className="h-4 bg-slate-200 rounded w-3/4"></div>
                      <div className="h-3 bg-slate-200 rounded w-1/2"></div>
                    </div>
                  </div>
                  <div className="space-y-3">
                    <div className="h-3 bg-slate-200 rounded"></div>
                    <div className="h-3 bg-slate-200 rounded w-5/6"></div>
                  </div>
                </div>
              ))}
            </div>
          ) : filteredOpportunities.length === 0 ? (
            <EmptyState 
              icon={SearchX}
              title="No opportunities available right now."
              description="Check back later or adjust your filters."
              actionText="Clear Filters"
              onAction={() => {
                setSearchQuery('');
                setSelectedTypes([]);
                setSelectedLocations([]);
                setSelectedCategories([]);
              }}
            />
          ) : (
            <>
              <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-6">
                {filteredOpportunities.map((opp) => (
                  <OpportunityCard 
                    key={opp.id} 
                    opp={opp} 
                    isSaved={isSaved(opp.id)} 
                    onSave={toggleSavedOpportunity} 
                    onApply={handleApply} 
                  />
                ))}
              </div>

              {/* Pagination Row */}
              <div className="mt-10 flex items-center justify-between bg-white px-6 py-4 rounded-[20px] border border-slate-100 shadow-[0_4px_20px_-4px_rgba(0,0,0,0.05)]">
                <div className="flex-1" />
                <div className="flex items-center gap-1">
                  <button 
                    aria-label="Previous page"
