                    <GraduationCap size={18} className="text-[#6C4CF1]" />
                  </div>
                  <div>
                    <p className="text-[14px] font-bold text-slate-900">{college}</p>
                    <p className="text-[12px] font-semibold text-[#6C4CF1] mt-0.5">{branch}</p>
                    <p className="text-[11px] font-medium text-slate-400 mt-0.5">Class of {gradYear}</p>
                  </div>
                </div>
              </Card>
            )}

            {/* Teams */}
            {myTeams.length > 0 && (
              <Card>
                <SectionHeader icon={Users} title="Teams" />
                <div className="flex flex-col gap-3">
                  {myTeams.slice(0, 4).map(team => (
                    <button
                      key={team.id}
                      onClick={() => navigate(`/team/${team.id}`)}
                      className="w-full flex items-center gap-3 p-3 rounded-xl hover:bg-slate-50 transition-colors text-left group"
                    >
                      <div className="w-9 h-9 rounded-xl bg-[#F4F2FF] flex items-center justify-center shrink-0">
                        <Users size={16} className="text-[#6C4CF1]" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-[13px] font-bold text-slate-900 truncate">{team.name}</p>
                        <p className="text-[11px] font-medium text-slate-500">{team.category}</p>
                      </div>
                      <ChevronRight size={14} className="text-slate-300 group-hover:text-slate-500 transition-colors shrink-0" />
                    </button>
                  ))}
                </div>
              </Card>
            )}

            {/* Resume Score */}
            <Card>
              <SectionHeader icon={FileText} title="Resume Score" />
              <div className="flex items-center gap-4 mb-4">
                <div className="relative w-20 h-20 shrink-0">
                  <svg className="w-20 h-20 -rotate-90" viewBox="0 0 80 80">
                    <circle cx="40" cy="40" r="32" fill="none" stroke="#F1F5F9" strokeWidth="8" />
                    <circle
                      cx="40" cy="40" r="32" fill="none"
                      stroke="#6C4CF1" strokeWidth="8" strokeLinecap="round"
                      strokeDasharray={`${2 * Math.PI * 32}`}
                      strokeDashoffset={`${2 * Math.PI * 32 * (1 - resumeScore / 100)}`}
                      className="transition-all duration-700"
                    />
                  </svg>
                  <div className="absolute inset-0 flex items-center justify-center">
                    <span className="text-[17px] font-extrabold text-slate-900">{resumeScore}%</span>
                  </div>
                </div>
                <div>
                  <p className="text-[14px] font-bold text-slate-900 mb-1">
                    {resumeScore >= 80 ? 'Excellent' : resumeScore >= 60 ? 'Good' : resumeScore >= 40 ? 'Fair' : 'Needs Work'}
                  </p>
                  <p className="text-[12px] font-medium text-slate-500 leading-relaxed">
                    {resumeScore < 80 ? 'Complete more sections in Create Resume to improve your score.' : 'Your profile is strong and ready to impress!'}
                  </p>
                </div>
              </div>
              <button
                onClick={() => navigate('/resume-builder')}
                className="w-full h-10 flex items-center justify-center gap-2 bg-[#F4F2FF] text-[#6C4CF1] text-[13px] font-bold rounded-xl hover:bg-indigo-100 transition-colors"
              >
                <FileText size={14} /> Edit Resume
              </button>
            </Card>

          </div>
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowRight, ArrowLeft, X, Rocket, CheckCircle2, Home } from 'lucide-react';
import DemoTimeline from './DemoTimeline';
import DemoPreviewCard from './DemoPreviewCard';

const DEMO_STEPS = [
  { id: 1, title: 'Create Profile', description: 'Set up your personal details, education, skills, and career interests.' },
  { id: 2, title: 'Personalized Dashboard', description: 'Get a personalized dashboard based on your profile, skills, and career goals.' },
  { id: 3, title: 'AI Resume Analysis', description: 'Upload your resume and receive AI-powered insights, ATS score, and improvement suggestions.' },
  { id: 4, title: 'Smart Opportunity Matching', description: 'Discover opportunities that match your skills, education, and interests.' },
  { id: 5, title: 'AI Career Coach', description: 'Receive personalized career guidance, ask questions, and get actionable recommendations.' },
  { id: 6, title: 'Career Roadmap', description: 'Generate a personalized learning roadmap to achieve your target career.' },
  { id: 7, title: 'Skill Gap Analysis', description: 'Identify missing skills and receive recommendations to improve your profile.' },
  { id: 8, title: 'Welcome to OpportunityOS', description: 'Your AI-powered career workspace is now ready. Launch your personalized dashboard.' }
];

export default function DemoPage() {
  const [currentStep, setCurrentStep] = useState(1);
  const navigate = useNavigate();

  const handleNext = () => {
    setCurrentStep(prev => prev + 1);
  };  

  const handlePrevious = () => {
    setCurrentStep(prev => Math.max(1, prev - 1));
  };

  const handleExit = () => {
    navigate('/signup');
  };

  const isCompleted = currentStep > DEMO_STEPS.length;

  if (isCompleted) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
