export const generateProjectRecommendations = async (profileData, forceRefresh = false) => {
  const specialization = profileData?.specialization || "Computer Science / Software Engineering";
  const targetRole = profileData?.targetRole || profileData?.careerGoal || "Software Engineer";
  const missingSkills = profileData?.missingSkills || [];

  // Create a unique cache key based on inputs
  const skillsKey = Array.isArray(missingSkills) ? missingSkills.join(',') : '';
  const cacheKey = `gemini_proj_recs_${specialization}_${targetRole}_${skillsKey}`;

  if (!forceRefresh) {
    const cachedData = sessionStorage.getItem(cacheKey);
    if (cachedData) {
      try {
        console.log(`[Project Engine] Cache hit for key: ${cacheKey}`);
        const parsed = JSON.parse(cachedData);
        // Ensure they are proper recommendation objects
        return parsed.map(proj => createRecommendation(proj));
      } catch (e) {
        console.warn("Invalid cache data, fetching fresh.");
      }
    }
  }

  // Track request count
  let requestCount = parseInt(sessionStorage.getItem('gemini_request_count') || '0', 10);
  requestCount += 1;
  sessionStorage.setItem('gemini_request_count', requestCount.toString());
  console.log(`[Project Engine] Gemini Request Count: ${requestCount}`);

  try {
    const rawProjects = await geminiService.generateProjectRecommendations({
      specialization,
      targetRole,
      missingSkills
    });

    if (!Array.isArray(rawProjects)) {
      throw new Error("Invalid response from Gemini API");
    }

    const formattedProjects = rawProjects.map(proj => createRecommendation({
      title: proj.title,
      description: proj.description,
      technologies: proj.technologies || [],
      whyThisProject: proj.whyThisProject,
      isMock: false
    }));

    // Save successful generation to cache
    sessionStorage.setItem(cacheKey, JSON.stringify(formattedProjects));

    // Also save a fallback copy in case another request fails
    sessionStorage.setItem('gemini_proj_recs_fallback', JSON.stringify(formattedProjects));

    return formattedProjects;
  } catch (error) {
    console.error("Gemini Project Recommendations Error:", error);

    // Attempt to use ANY previously cached recommendations as a fallback
    const fallbackData = sessionStorage.getItem('gemini_proj_recs_fallback');
    if (fallbackData) {
      try {
        console.log("[Project Engine] Using fallback cached data due to Gemini failure.");
        const parsedFallback = JSON.parse(fallbackData);
        return parsedFallback.map(proj => createRecommendation(proj));
      } catch (e) {
        console.warn("Invalid fallback cache data.");
      }
    }

    console.warn("[Dev Fallback] AI service busy and no cache available. Generating mock recommendations.");
    return generateMockRecommendations(specialization, targetRole);
  }
};

import * as pdfjsLib from 'pdfjs-dist';
import mammoth from 'mammoth';
import pdfWorkerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url';

// Initialize PDF.js worker
if (typeof window !== 'undefined' && 'Worker' in window) {
  pdfjsLib.GlobalWorkerOptions.workerSrc = pdfWorkerUrl;
}

export const fileToBase64 = (file) => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result;
      const base64Data = result.split(',')[1];
      resolve({
        mimeType: file.type || 'application/pdf',
        base64: base64Data
      });
    };
    reader.onerror = error => reject(error);
  });
};

export const extractTextFromFile = async (file) => {
  return new Promise((resolve, reject) => {
    try {
      const reader = new FileReader();

      reader.onload = async (e) => {
        const arrayBuffer = e.target.result;
        try {
          let text = '';
          const fileType = file.type || '';
          const fileName = file.name || '';

          if (fileType === 'application/pdf' || fileName.toLowerCase().endsWith('.pdf')) {
            try {
              const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
              let extractedText = '';
              for (let i = 1; i <= pdf.numPages; i++) {
                const page = await pdf.getPage(i);
                const textContent = await page.getTextContent();
                const pageText = textContent.items.map(item => item.str).join(' ');
                extractedText += pageText + ' ';
              }
              text = extractedText;
            } catch (pdfErr) {
              const error = new Error('Unable to read this PDF file.');
              error.type = 'PDF_EXTRACTION_FAILURE';
              error.original = pdfErr;
              throw error;
            }
          } else if (fileType === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' || fileName.toLowerCase().endsWith('.docx')) {
            try {
              const result = await mammoth.extractRawText({ arrayBuffer });
              text = result.value;
            } catch (docxErr) {
              const error = new Error('Unable to process this DOCX file.');
              error.type = 'DOCX_EXTRACTION_FAILURE';
              error.original = docxErr;
              throw error;
            }
          } else if (fileType.startsWith('text/') || fileName.toLowerCase().endsWith('.txt')) {
            const textDecoder = new TextDecoder('utf-8');
            text = textDecoder.decode(arrayBuffer);
          } else {
            const error = new Error('Unsupported file format.');
            error.type = 'UNSUPPORTED_FILE';
            throw error;
          }

          resolve(text.trim());
        } catch (err) {
          reject(err);
        }
      };

      reader.onerror = () => reject(new Error('Failed to read file'));
      reader.readAsArrayBuffer(file);
    } catch (err) {
      reject(err);
    }
  });
};

export const optimizeLargeResumeText = (text, maxLength = 25000) => {
  if (!text) return '';

  // Clean whitespace and repeated newlines
  let cleanText = text.replace(/\n\s*\n/g, '\n\n').replace(/[ \t]{2,}/g, ' ').trim();

  if (cleanText.length <= maxLength) return cleanText;

  // Split by double newlines to keep sections intact
  const chunks = cleanText.split('\n\n');
  let optimizedText = '';

  for (const chunk of chunks) {
    // Ignore purely decorative chunks
    if (/^[=_\-*\| ]+$/.test(chunk.trim())) continue;

    if (optimizedText.length + chunk.length + 2 > maxLength) {
      optimizedText += '\n\n...[Content truncated to optimize AI processing]';
      break;
    }
    optimizedText += chunk + '\n\n';
  }

  return optimizedText.trim();
};

/**
 * Utility to deeply analyze GitHub portfolio and calculate metrics.
 */

// Helper to fetch the actual 52-week contribution heatmap
export async function fetchContributionHeatmap(username) {
  try {
    const res = await fetch(`https://github-contributions-api.jasonbarry.com/v1/${username}`);
    if (!res.ok) throw new Error("Heatmap fetch failed");
    const data = await res.json();

    // We want the last 52 weeks of data
    const weeks = data?.contributions || [];
    let totalContributions = 0;

    // Create a 52x7 matrix for the UI
    const heatmap = [];

    // The API returns an array of weeks (each week has an array of days)
    // We need the last 52 weeks
    const last52Weeks = weeks.slice(-52);

    last52Weeks.forEach(week => {
      const weekData = [];
      for (let j = 0; j < 7; j++) {
        const day = week.days[j];
        if (day) {
          totalContributions += day.count;
          // Map count to an intensity scale 0-4
          let intensity = 0;
          if (day.count > 0) intensity = 1;
          if (day.count > 3) intensity = 2;
          if (day.count > 6) intensity = 3;
          if (day.count > 10) intensity = 4;
          weekData.push(intensity);
        } else {
          weekData.push(0);
        }
      }
      heatmap.push(weekData);
    });

    // Ensure we have exactly 52 weeks
    while (heatmap.length < 52) {
      heatmap.unshift(Array(7).fill(0));
    }

    return { heatmap, totalContributions };
  } catch (err) {
    console.warn("Failed to fetch real heatmap from proxy, falling back to Events API:", err);
    const heatmap = Array.from({ length: 52 }, () => Array(7).fill(0));
    let totalContributions = 0;

    try {
      // Fallback: fetch recent events (up to 90 days, but max 100 events per page)
      const evRes = await fetch(`https://api.github.com/users/${username}/events?per_page=100`);
      if (evRes.ok) {
        const events = await evRes.json();
        const now = new Date();
        events.forEach(ev => {
          if (['PushEvent', 'CreateEvent', 'PullRequestEvent', 'IssuesEvent'].includes(ev.type)) {
            const d = new Date(ev.created_at);
            const diffTime = Math.abs(now - d);
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
            if (diffDays < 365) {
              const weekIdx = 51 - Math.floor(diffDays / 7);
              const dayIdx = d.getDay();
              if (heatmap[weekIdx] && heatmap[weekIdx][dayIdx] !== undefined) {
                 heatmap[weekIdx][dayIdx] = Math.min(heatmap[weekIdx][dayIdx] + 1, 4);
                 totalContributions++;
              }
            }
          }
        });
      }
    } catch (e) {
      console.warn("Fallback Events API also failed:", e);
    }

    return { heatmap, totalContributions };
  }
}

// Deeply fetch data for Top 5 repositories
export async function fetchDeepGithubData(username, allRepos) {
  // Sort by stars, then forks, then updated
  const sortedRepos = [...allRepos].sort((a, b) => {
    if (b.stargazers_count !== a.stargazers_count) return b.stargazers_count - a.stargazers_count;
    if (b.forks_count !== a.forks_count) return b.forks_count - a.forks_count;
    return new Date(b.updated_at) - new Date(a.updated_at);
  });

  const top5 = sortedRepos.slice(0, 5);
  const deepAnalysis = [];

  const headers = { 'Accept': 'application/vnd.github.v3+json' };

  await Promise.allSettled(top5.map(async (repo) => {
    try {
      let readme = "";
      let packageJson = null;
      let requirementsTxt = null;
      let hasActions = false;
      let hasDocker = false;

      // Fetch Tree (limit to 1 level for speed, or recursive if small)
      const treeRes = await fetch(`https://api.github.com/repos/${username}/${repo.name}/git/trees/${repo.default_branch}?recursive=1`, { headers });
      if (treeRes.ok) {
        const treeData = await treeRes.json();
        const files = treeData.tree || [];

        const filePaths = files.map(f => f.path.toLowerCase());
        hasActions = filePaths.some(p => p.includes('.github/workflows/'));
        hasDocker = filePaths.some(p => p.includes('dockerfile') || p.includes('docker-compose'));

        // If package.json exists, fetch it
        if (filePaths.includes('package.json')) {
          const pkgRes = await fetch(`https://raw.githubusercontent.com/${username}/${repo.name}/${repo.default_branch}/package.json`);
          if (pkgRes.ok) packageJson = await pkgRes.text();
        }

        // If requirements.txt exists, fetch it
        if (filePaths.includes('requirements.txt')) {
          const reqRes = await fetch(`https://raw.githubusercontent.com/${username}/${repo.name}/${repo.default_branch}/requirements.txt`);
          if (reqRes.ok) requirementsTxt = await reqRes.text();
        }
      }

      // Fetch README
      const readmeRes = await fetch(`https://raw.githubusercontent.com/${username}/${repo.name}/${repo.default_branch}/README.md`);
      if (readmeRes.ok) {
        readme = await readmeRes.text();
      }

      deepAnalysis.push({
        repoName: repo.name,
        readme: readme.substring(0, 2000), // truncate for AI token limits
        packageJson: packageJson ? packageJson.substring(0, 1000) : null,
        requirementsTxt,
        hasActions,
        hasDocker
      });
    } catch (e) {
      console.warn(`Failed to deep fetch ${repo.name}`, e);
    }
  }));

  return deepAnalysis;
}

export function calculateLocalGithubMetrics(githubData, userData, targetRole) {
  let stars = 0;
  let forks = 0;
  let repoCount = githubData.length;
  let languageCounts = {};
  let topics = new Set();

  // Calculate raw metrics
  githubData.forEach(repo => {
    stars += repo.stargazers_count || 0;
    forks += repo.forks_count || 0;
    if (repo.language) {
      languageCounts[repo.language] = (languageCounts[repo.language] || 0) + 1;
    }
    if (repo.topics) {
      repo.topics.forEach(t => topics.add(t));
    }
  });

  const languagesArray = Object.entries(languageCounts).map(([name, count]) => ({
    name,
    count
  })).sort((a, b) => b.count - a.count);

  let totalLanguages = languagesArray.reduce((acc, l) => acc + l.count, 0);

  const languageStats = languagesArray.map(l => ({
    name: l.name,
    percentage: totalLanguages > 0 ? Math.round((l.count / totalLanguages) * 100) : 0
  }));

  // Extracted Technology
  const detected = languagesArray.map(l => l.name);

  // Calculate Years Active
  let activeSince = 0;
  if (userData && userData.created_at) {
    activeSince = new Date().getFullYear() - new Date(userData.created_at).getFullYear();
    if (activeSince === 0) activeSince = 1; // Minimum 1 year
  }

  return {
    basicStats: {
      publicRepos: userData?.public_repos || repoCount,
      followers: userData?.followers || 0,
      following: userData?.following || 0,
      totalStars: stars,
      activeSince: activeSince
    },
    languageStats,
    technologyAnalysis: {
      detected
    },
    repos: githubData
  };
}

export const getUserFirstName = (user, profile = null) => {
  if (user?.displayName) {
    return user.displayName; // use the exact displayName
  }
  if (profile?.full_name) {
    return profile.full_name.split(' ')[0];
  }
  if (profile?.name) {
    return profile.name.split(' ')[0];
  }
  if (user?.name) {
    return user.name.split(' ')[0];
  }
  if (user?.email) {
    // Try to extract a clean first name from email by removing numbers/symbols
    const namePart = user.email.split('@')[0].split(/[\._0-9]/)[0];
    if (namePart && namePart.length > 1) {
      return namePart.charAt(0).toUpperCase() + namePart.slice(1).toLowerCase();
    }
  }
  return null; // Return null so we can fallback to just "Welcome back! 👋"
};

export const getUserFullName = (user, profile = null) => {
  if (user?.displayName) {
    return user.displayName;
  }
  if (profile?.full_name) {
    return profile.full_name;
  }
  if (profile?.name) {
    return profile.name;
  }
  if (user?.name) {
    return user.name;
  }
  if (user?.email) {
    const namePart = user.email.split('@')[0].split(/[\._0-9]/)[0];
    if (namePart && namePart.length > 1) {
      return namePart.charAt(0).toUpperCase() + namePart.slice(1).toLowerCase();
    }
  }
  return 'User'; // Generic fallback
};
